import sys, re, subprocess, os, argparse

def decode(capture_text):
    """Return grid of (char, fg, bg, style_set) tuples list of rows."""
    rows = capture_text.split('\n')
    grid = []
    for line in rows:
        cells = []
        fg, bg, style = 'Default', 'Default', set()
        i = 0
        while i < len(line):
            if line[i] == '\x1b':
                m = re.match(r'\x1b\[([0-9;]*)m', line[i:])
                if m:
                    params = m.group(1)
                    i += m.end()
                    ps = [p for p in params.split(';') if p != '']
                    if not ps:
                        ps = ['0']
                    j = 0
                    while j < len(ps):
                        p = ps[j]
                        n = int(p)
                        if n == 0:
                            fg, bg, style = 'Default','Default',set()
                        elif n in (1,): style.add('bold')
                        elif n == 2: style.add('dim')
                        elif n == 3: style.add('italic')
                        elif n == 4: style.add('underlined')
                        elif n == 5: style.add('blink')
                        elif n == 7: style.add('inverted')
                        elif n == 9: style.add('strikethrough')
                        elif n == 22: style.discard('bold'); style.discard('dim')
                        elif n == 23: style.discard('italic')
                        elif n == 24: style.discard('underlined')
                        elif n == 25: style.discard('blink')
                        elif n == 27: style.discard('inverted')
                        elif n == 29: style.discard('strikethrough')
                        elif 30 <= n <= 37: fg = 'ansi16-%d'%(n-30)
                        elif n == 39: fg = 'Default'
                        elif 40 <= n <= 47: bg = 'ansi16-%d'%(n-40)
                        elif n == 49: bg = 'Default'
                        elif 90 <= n <= 97: fg = 'ansi16-%d'%(n-90+8)
                        elif 100 <= n <= 107: bg = 'ansi16-%d'%(n-100+8)
                        elif n in (38,48):
                            tgt = 'fg' if n==38 else 'bg'
                            if j+1 < len(ps) and ps[j+1] == '5':
                                col = 'ansi256-%d' % int(ps[j+2]); j += 2
                            elif j+1 < len(ps) and ps[j+1] == '2':
                                col = 'rgb(%s,%s,%s)' % (ps[j+2],ps[j+3],ps[j+4]); j += 4
                            else:
                                col = '?'
                            if tgt=='fg': fg = col
                            else: bg = col
                        j += 1
                    continue
                else:
                    m2 = re.match(r'\x1b.', line[i:])
                    i += m2.end() if m2 else 1
                    continue
            cells.append((line[i], fg, bg, frozenset(style)))
            i += 1
        grid.append(cells)
    return grid

def render(grid, width=None, show_style=False):
    out = []
    for row in grid:
        if show_style:
            out.append(''.join('%s[%s%s]' % (c, fg[0].upper()+fg[1:], bg if bg!='Default' else '') for c,fg,bg,st in row))
        else:
            out.append(''.join(c for c,fg,bg,st in row))
    return '\n'.join(out)

if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('session')
    ap.add_argument('--style', action='store_true')
    ap.add_argument('--out')
    a = ap.parse_args()
    txt = subprocess.run(['tmux','capture-pane','-t',a.session,'-p','-e'], capture_output=True).stdout.decode('utf-8','replace')
    g = decode(txt)
    s = render(g, show_style=a.style)
    if a.out:
        open(a.out,'w').write(s)
    else:
        sys.stdout.write(s)
