        if '╭2026' in r or '╭January' in r or '╭Febr' in r or '╭Marc' in r or '╭A' in r and False: pass
    # preview box
    if 'previewtitle' in info:
        pt=info['previewtitle']
        left=rows[pt].index('│',0)
        # top border row = pt-1
        top=pt-1
        b=top
        while b+1<len(rows) and rows[b+1][left]!='╰': b+=1
        info['previewbox']=(top,b)
    if 'events' in info:
        e=info['events']
        left=rows[e].index('╭')
        b=e
        while b+1<len(rows) and rows[b+1][left]!='╰': b+=1
        info['eventsbox']=(e,b)
    # calendar top: row above the first row containing '╭' in calendar area
    if 'events' in info:
        e=info['events']
        # find calendar box: look for a row containing '╭' at col > menus end
        for i,r in enumerate(rows):
            for j,ch in enumerate(r):
                if ch=='╭' and j>0 and 'Sections' in r and j>r.index('╭Sections')+24:
                    info['calbox_top']=i; break
            if 'calbox_top' in info: break
        if 'calbox_top' in info:
            i=info['calbox_top']
            # find rightmost border col
            # find bottom: scan down from i for row where char at some col is '╰' after the last month
            # locate left border col = first '│' after menus
            # approximate: find row with '╰' at end (last row with '╰' before preview top)
            prev=info.get('previewbox',(len(rows),0))[0]
            bb=i
            for k in range(i+1,prev):
                if rows[k].rstrip().endswith('╯') and rows[k].count('╰')>=1 and 'Sections' not in rows[k] and 'Recent' not in rows[k]:
                    bb=k
            info['calbox']=(i,bb)
    print('W=%d H=%d'%(W,len(rows)))
    print(' title row %s; help %s'%(info.get('title'),info.get('help')))
    print(' menus  rows %s ..'%(info.get('menus')))
    if 'events' in info:
        print(' eventsbox rows %s'% (info['eventsbox'],))
    if 'calbox' in info: print(' calbox rows %s'% (info['calbox'],))
    if 'previewbox' in info: print(' previewbox rows %s'% (info['previewbox'],))
    # column extents of each box in a representative row
    def cols(i):
        r=rows[i]
        return [(j,ch) for j,ch in enumerate(r) if ch in '╭╮╰╯│├┤┬┴']
    for name,i in [('menus',info.get('menus')),('events',info.get('events'))]:
        if i is None: continue
        print(' %s row%d: %s'%(name,i+1,''.join('%d:%s '%(j,c) for j,c in cols(i))[:400]))
    if 'previewbox' in info:
        print(' preview row%d: %s'%(info['previewbox'][0]+1, ''.join('%d:%s '%(j,c) for j,c in cols(info['previewbox'][0]))[:400]))
main(sys.argv[1])
