        if 'Recent & upcoming' in r: info.setdefault('events',i)
        if 'Sections' in r: info.setdefault('menus',i)
        if '╭2026' in r: info.setdefault('yeartop',i)
    def find_bottom(i,left):
        b=i
        while b+1<len(rows) and rows[b+1][left]!='╰': b+=1
        return b
    if 'previewtitle' in info:
        pt=info['previewtitle']; left=rows[pt].index('│')
        top=pt-1
        info['previewbox']=(top,find_bottom(top,left),left)
    if 'events' in info:
        e=info['events']; left=rows[e].index('╭')
