        info['menusbox']=(m,find_bottom(m,left),left)
    if 'yeartop' in info:
        y=info['yeartop']; left=rows[y].index('╭',rows[m].index('╭Sections') if 'menus' in info else 0)
        # right col
        rr=rows[y].rindex('╮')
        info['yearbox']=(y,find_bottom(y,left),left,rr)
