    print('  menusbox=%s eventsbox=%s yearbox=%s previewbox=%s'%(info.get('menusbox'),info.get('eventsbox'),info.get('yearbox'),info.get('previewbox')))
    if 'menusbox' in info:
        m=info['menusbox']
        r=rows[m[0]]
        seg=[]
        j=0
        while True:
            k=r.find('╭',j)
            if k<0: break
            e2=r.find('╮',k)
            seg.append('%d-%d(%d)'%(k,e2,e2-k+1))
            j=e2+1
        print('  top-border boxes: %s'%(' '.join(seg)))
main(sys.argv[1])
