def run(cmd,w=160,h=60,term='screen',keys=b'',wait=1.0):
    pid,fd=pty.fork()
    if pid==0:
        env=dict(os.environ); env['TERM']=term
        os.execvpe(cmd[0],cmd,env)
    fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',h,w,0,0))
    out=b''
    def drain():
        nonlocal out
        while True:
            r,_,_=select.select([fd],[],[],0.05)
            if not r: break
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d
    drain()
    for k in keys.split(b'\x00'):
        if k==b'': continue
        os.write(fd,k); time.sleep(0.1); drain()
    time.sleep(wait); drain()
    os.close(fd)
    try: os.waitpid(pid,0)
    except Exception: pass
    return out.decode('utf-8','replace')
KEYS=['header1','header2','header3','header4','header5','header6','list','quote','code-fg']
def mkcfg(vals):
    s='log-dir-path=/tmp/L3\n[view.annual-view.theme.log-entry-preview.markdown-theme]\n'
    for k,v in zip(KEYS,vals): s+='%s=%s\n'%(k,v)
    return s
results={}
for start in range(0,256,9):
    idxs=list(range(start,min(start+9,256)))
    vals=['ansi256(%d)'%i for i in idxs]
    open('/tmp/confT/config.ini','w').write(mkcfg(vals))
    d=run(['/workspace/executable','--config','/tmp/confT/config.ini'],term='screen')
    # for each line in the preview find the code before each text
    # simpler: collect all codes present
    codes=sorted(set(re.findall(r'\x1b\[(3\d|9\d|m)m',d)))
    # map: find the order of appearance for each key by locating the text markers
    lines=d.split('\r\r\n')
    # find lines for each header level
    marks={'header1':'# 15. 10. 24.','header2':'## Header Two','header3':'### Header Three','header4':'#### Header Four','header5':'##### Header Five','header6':'###### Header Six','list':'* tagA','quote':'> quote line','code-fg':'```python'}
    for k,m in marks.items():
        got=None
        for l in lines:
            if m in l:
                mm=re.search(r'\x1b\[(3\d|9\d|m)m',l)
                if mm: got=mm.group(1)
                break
        if got: results[idxs[KEYS.index(k)]]=got
    print('.',end='',flush=True)
print()
for k in sorted(results): print(k, results[k])
