import subprocess,sys,re
sys.path.insert(0,'/tmp/tools')
from grid import decode
MN=['January','February','March','April','May','June','July','August','September','October','November','December']
def boxes(s):
    rows=[''.join(c for c,f,b,st in row) for row in decode(subprocess.run(['tmux','capture-pane','-t',s,'-p','-e'],capture_output=True).stdout.decode('utf-8','replace'))]
    pw=subprocess.run(['tmux','display','-p','-t',s,'#{pane_width} #{pane_height}'],capture_output=True).stdout.decode().strip()
    res={'pane':pw}
    pad=None
    for r in rows:
        if 'Today is:' in r: pad=len(r)-len(r.lstrip()); break
    res['pad']=pad
    def findbox(marker, ch_open='╭', ch_close='╮'):
        for r in rows:
            i=r.find(marker)
            if i>=0:
                a=r.rfind(ch_open,0,i)
                e=r.find(ch_close,i)
                if a>=0 and e>=0: return (a,e)
        return None
    res['sections']=findbox('Sections')
    res['tags']=findbox('Tags')
    res['events']=findbox('Recent')
    # preview box: find the row with 'log preview' then the box borders
    for i,r in enumerate(rows):
        if 'log preview' in r:
            a=r.find('│'); e=r.rfind('│')
            res['preview']=(a,e)
            break
    # year box
    for r in rows:
        m=re.search(r'╭(\d{4})',r)
        if m:
            e=r.find('╮',m.start())
            if e>=0: res['year']=(m.start(),e)
            break
    # month columns
    mcols=0
    for r in rows:
        n=len([m for m in re.finditer(r'╭([A-Z][a-z]+)',r) if m.group(1) in MN])
        mcols=max(mcols,n)
    res['mcols']=mcols
    # help line
    for r in rows:
        if 'hjkl' in r:
            res['helplead']=len(r)-len(r.lstrip()); break
    print(s, res)
if __name__=='__main__':
    for s in sys.argv[1:]: boxes(s)
