    int tr = 0, tg = 0, tb = 0;
    if (c.type == ColorType::Rgb) { tr = c.r; tg = c.g; tb = c.b; }
    else if (c.type == ColorType::Ansi256) { palette256_rgb(c.v, &tr, &tg, &tb); }
