#include "term.h"
#include <unistd.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <fcntl.h>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <signal.h>

namespace cl {

static struct termios g_orig;
static bool g_raw = false;

Terminal::Terminal() {}
Terminal::~Terminal() { if (g_raw) teardown(); }

bool Terminal::init() {
    if (!isatty(0)) return false;
    struct termios t;
    if (tcgetattr(0, &t) != 0) return false;
    g_orig = t;
    struct termios r = t;
    r.c_iflag &= ~(unsigned)(IXON | ICRNL | BRKINT | INPCK | ISTRIP);
    r.c_oflag &= ~(unsigned)(OPOST);
    r.c_lflag &= ~(unsigned)(ECHO | ICANON | ISIG | IEXTEN);
    r.c_cflag &= ~(unsigned)(CSIZE | PARENB);
    r.c_cflag |= CS8;
    r.c_cc[VMIN] = 1;
    r.c_cc[VTIME] = 0;
    if (tcsetattr(0, TCSANOW, &r) != 0) return false;
    g_raw = true;
    return true;
}

void Terminal::teardown() {
    if (g_raw) tcsetattr(0, TCSANOW, &g_orig);
    g_raw = false;
}

TermSize Terminal::size() const {
    struct winsize ws;
    if (ioctl(1, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0)
        return TermSize{(int)ws.ws_col, (int)ws.ws_row};
    if (ioctl(0, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0)
        return TermSize{(int)ws.ws_col, (int)ws.ws_row};
    return TermSize{80, 24};
}

// decode a utf-8 sequence starting at p
static uint32_t decode_utf8(const unsigned char* p, int len, int* used) {
    if (len <= 0) { *used = 0; return 0; }
    unsigned char c = p[0];
    if (c < 0x80) { *used = 1; return c; }
    if ((c & 0xE0) == 0xC0 && len >= 2) { *used = 2; return ((c & 0x1F) << 6) | (p[1] & 0x3F); }
    if ((c & 0xF0) == 0xE0 && len >= 3) { *used = 3; return ((c & 0x0F) << 12) | ((p[1] & 0x3F) << 6) | (p[2] & 0x3F); }
    if ((c & 0xF8) == 0xF0 && len >= 4) { *used = 4; return ((c & 0x07) << 18) | ((p[1] & 0x3F) << 12) | ((p[2] & 0x3F) << 6) | (p[3] & 0x3F); }
    *used = 1; return c;
}

bool Terminal::read_key(KeyEv& ev, int timeout_ms) {
    static std::vector<unsigned char> buf;
    while (true) {
        // try to parse what we have
        if (!buf.empty()) {
            unsigned char c = buf[0];
            if (c == 0x1b) {
                if (buf.size() == 1) {
                    // maybe an incomplete escape: poll for more
                    fd_set fds;
                    struct timeval tv{0, 20000};
                    FD_ZERO(&fds); FD_SET(0, &fds);
                    if (select(1, &fds, nullptr, nullptr, &tv) > 0) {
                        unsigned char tmp[64];
                        int n = read(0, tmp, sizeof(tmp));
                        for (int i = 0; i < n; ++i) buf.push_back(tmp[i]);
                        continue;
                    }
                    buf.erase(buf.begin());
                    ev.type = KeyType::Escape;
                    return true;
                }
                if (buf.size() >= 2 && (buf[1] == '[' || buf[1] == 'O')) {
                    // CSI / SS3
                    size_t i = 2;
                    bool done = false;
                    std::string params;
                    if (buf[1] == 'O') {
                        if (buf.size() >= 3) {
                            char f = buf[2];
                            buf.erase(buf.begin(), buf.begin() + 3);
                            switch (f) {
                                case 'A': ev.type = KeyType::Up; return true;
                                case 'B': ev.type = KeyType::Down; return true;
                                case 'C': ev.type = KeyType::Right; return true;
                                case 'D': ev.type = KeyType::Left; return true;
                                case 'H': ev.type = KeyType::Home; return true;
                                case 'F': ev.type = KeyType::End; return true;
                                case 'P': ev.type = KeyType::F1; return true;
                                case 'Q': ev.type = KeyType::Other; return true;
                                default: ev.type = KeyType::Other; return true;
                            }
                        }
                    } else {
                        while (i < buf.size()) {
                            unsigned char d = buf[i];
                            if (d >= '0' && d <= '9') { params += (char)d; ++i; continue; }
                            if (d == ';') { params += ';'; ++i; continue; }
                            if (d == '<') { params += '<'; ++i; continue; }
                            if (d == 'M' || d == 'm') {
                                // mouse
                                int nums[8] = {0};
                                int nn = 0;
                                size_t k = 0;
                                std::string cur;
                                for (char ch : params) {
                                    if (ch == ';' || ch == '<') { if (nn < 8) nums[nn++] = atoi(cur.c_str()); cur.clear(); }
                                    else cur += ch;
                                }
                                if (!cur.empty() && nn < 8) nums[nn++] = atoi(cur.c_str());
                                buf.erase(buf.begin(), buf.begin() + i + 1);
                                ev.type = KeyType::Mouse;
                                ev.mouse.press = (d == 'M');
                                ev.mouse.release = (d == 'm');
                                if (nn >= 1) ev.mouse.button = nums[0];
                                if (nn >= 2) ev.mouse.x = nums[1] - 1;
                                if (nn >= 3) ev.mouse.y = nums[2] - 1;
                                return true;
                            }
                            if (d == '~') {
                                int num = params.empty() ? 0 : atoi(params.c_str());
                                buf.erase(buf.begin(), buf.begin() + i + 1);
                                switch (num) {
                                    case 1: case 7: ev.type = KeyType::Home; return true;
                                    case 2: ev.type = KeyType::Other; return true;
                                    case 3: ev.type = KeyType::Delete; return true;
                                    case 4: case 8: ev.type = KeyType::End; return true;
                                    case 5: ev.type = KeyType::PageUp; return true;
                                    case 6: ev.type = KeyType::PageDown; return true;
                                    case 11: case 15: ev.type = KeyType::F1; return true;
                                    default: ev.type = KeyType::Other; return true;
                                }
                            }
                            if ((d >= 'A' && d <= 'Z') || (d >= 'a' && d <= 'z')) {
                                char f = d;
                                buf.erase(buf.begin(), buf.begin() + i + 1);
                                switch (f) {
                                    case 'A': ev.type = KeyType::Up; return true;
                                    case 'B': ev.type = KeyType::Down; return true;
                                    case 'C': ev.type = KeyType::Right; return true;
                                    case 'D': ev.type = KeyType::Left; return true;
                                    case 'H': ev.type = KeyType::Home; return true;
                                    case 'F': ev.type = KeyType::End; return true;
                                    case 'Z': ev.type = KeyType::BackTab; return true;
                                    default: ev.type = KeyType::Other; return true;
                                }
                            }
                            ++i;
                        }
                    }
                    if (!done) {
                        // incomplete; wait for more
                        fd_set fds;
                        struct timeval tv{0, 20000};
                        FD_ZERO(&fds); FD_SET(0, &fds);
                        if (select(1, &fds, nullptr, nullptr, &tv) > 0) {
                            unsigned char tmp[64];
                            int n = read(0, tmp, sizeof(tmp));
                            for (int k = 0; k < n; ++k) buf.push_back(tmp[k]);
                            continue;
                        }
                        buf.erase(buf.begin(), buf.begin() + 1);
                        ev.type = KeyType::Escape;
                        return true;
                    }
                }
                buf.erase(buf.begin(), buf.begin() + 1);
                ev.type = KeyType::Escape;
                return true;
            } else if (c == '\r' || c == '\n') {
                buf.erase(buf.begin());
                ev.type = KeyType::Enter;
                return true;
            } else if (c == '\t') {
                buf.erase(buf.begin());
                ev.type = KeyType::Tab;
                return true;
            } else if (c == 0x7f || c == 0x08) {
                buf.erase(buf.begin());
                ev.type = KeyType::Backspace;
                return true;
            } else if (c == 0x00) {
                buf.erase(buf.begin());
                ev.type = KeyType::Other;
                return true;
            } else if (c < 0x20) {
                buf.erase(buf.begin());
                ev.type = KeyType::Other;
                ev.ch = c;
                return true;
            } else {
                int used = 0;
                uint32_t cp = decode_utf8(buf.data(), (int)buf.size(), &used);
                if (used == 0) {
                    // need more bytes
                    fd_set fds;
                    struct timeval tv{0, 20000};
                    FD_ZERO(&fds); FD_SET(0, &fds);
                    if (select(1, &fds, nullptr, nullptr, &tv) > 0) {
                        unsigned char tmp[8];
                        int n = read(0, tmp, sizeof(tmp));
                        for (int k = 0; k < n; ++k) buf.push_back(tmp[k]);
                        continue;
                    }
                    buf.erase(buf.begin());
                    ev.type = KeyType::Char;
                    ev.ch = '?';
                    return true;
                }
                buf.erase(buf.begin(), buf.begin() + used);
                ev.type = KeyType::Char;
                ev.ch = cp;
                return true;
            }
        }
