#include "render.h"
#include <cstdio>

namespace cl {

int char_width(uint32_t cp) {
    if (cp == 0) return 0;
    if (cp < 0x20) return 0;
    if (cp >= 0x1100 && cp <= 0x115F) return 2;   // hangul jamo
    if (cp >= 0x2E80 && cp <= 0xA4CF && cp != 0x303F) return 2;
    if (cp >= 0xAC00 && cp <= 0xD7A3) return 2;
    if (cp >= 0xF900 && cp <= 0xFAFF) return 2;
    if (cp >= 0xFE30 && cp <= 0xFE6F) return 2;
    if (cp >= 0xFF00 && cp <= 0xFF60) return 2;
    if (cp >= 0xFFE0 && cp <= 0xFFE6) return 2;
    if (cp >= 0x1F300 && cp <= 0x1F64F) return 2;
    if (cp >= 0x1F900 && cp <= 0x1F9FF) return 2;
    if (cp >= 0x20000 && cp <= 0x3FFFD) return 2;
    return 1;
}

static void append_attr(std::string& out, int code) {
    char buf[32];
    snprintf(buf, sizeof(buf), "\x1b[%dm", code);
    out += buf;
}

static void append_fg(std::string& out, const ColorOut& c) {
    if (c.is_default) { append_attr(out, 39); return; }
    if (c.ansi16 <= 7) { append_attr(out, 30 + c.ansi16); return; }
    append_attr(out, 90 + (c.ansi16 - 8));
}

static void append_bg(std::string& out, const ColorOut& c) {
    if (c.is_default) { append_attr(out, 49); return; }
    if (c.ansi16 <= 7) { append_attr(out, 40 + c.ansi16); return; }
    append_attr(out, 100 + (c.ansi16 - 8));
}

static void append_fg256(std::string& out, const ColorOut& c) {
    if (c.is_default) { append_attr(out, 39); return; }
    if (c.ansi16 <= 7) { append_attr(out, 30 + c.ansi16); return; }
    if (c.ansi16 <= 15) { append_attr(out, 90 + (c.ansi16 - 8)); return; }
    char buf[32];
    snprintf(buf, sizeof(buf), "\x1b[38;5;%dm", c.a256);
    out += buf;
}

static void append_bg256(std::string& out, const ColorOut& c) {
    if (c.is_default) { append_attr(out, 49); return; }
    if (c.ansi16 <= 7) { append_attr(out, 40 + c.ansi16); return; }
    if (c.ansi16 <= 15) { append_attr(out, 100 + (c.ansi16 - 8)); return; }
    char buf[32];
    snprintf(buf, sizeof(buf), "\x1b[48;5;%dm", c.a256);
    out += buf;
}

std::string Renderer::render(const Screen& s) {
    std::string out;
    Style cur;   // all default
    auto emit_style = [&](const Style& st) {
        if (st == cur) return;
        // attributes that turned off
        bool need_on = false;
        auto off = [&](bool was, bool now) { return was && !now; };
        bool offbold = off(cur.bold, st.bold), offdim = off(cur.dim, st.dim),
             offital = off(cur.italic, st.italic), offund = off(cur.underline, st.underline),
             offblink = off(cur.blink, st.blink), offinv = off(cur.inverted, st.inverted),
             offstrike = off(cur.strikethrough, st.strikethrough);
        bool any_off = offbold || offdim || offital || offund || offblink || offinv || offstrike;
        if (any_off) {
            if (offbold || offdim) append_attr(out, 22);
            if (offital) append_attr(out, 23);
            if (offund) append_attr(out, 24);
            if (offblink) append_attr(out, 25);
            if (offinv) append_attr(out, 27);
            if (offstrike) append_attr(out, 29);
            need_on = true;
        }
        bool any_on = (st.bold && !cur.bold) || (st.dim && !cur.dim) || (st.italic && !cur.italic) ||
                      (st.underline && !cur.underline) || (st.blink && !cur.blink) ||
                      (st.inverted && !cur.inverted) || (st.strikethrough && !cur.strikethrough);
        if (any_on || need_on) {
            if (st.bold) append_attr(out, 1);
            if (st.dim) append_attr(out, 2);
            if (st.italic) append_attr(out, 3);
            if (st.underline) append_attr(out, 4);
            if (st.blink) append_attr(out, 5);
            if (st.inverted) append_attr(out, 7);
            if (st.strikethrough) append_attr(out, 9);
        }
        bool fgc = !(st.fg == cur.fg), bgc = !(st.bg == cur.bg);
        if (fgc || bgc) {
            if (term256_) { append_fg256(out, resolve_color(st.fg, true)); append_bg256(out, resolve_color(st.bg, true)); }
            else { append_fg(out, resolve_color(st.fg, false)); append_bg(out, resolve_color(st.bg, false)); }
        }
        cur = st;
    };
    auto end_line = [&]() {
        bool wrote = false;
        if (cur.bold || cur.dim) { append_attr(out, 22); wrote = true; }
        if (cur.italic) { append_attr(out, 23); wrote = true; }
        if (cur.underline) { append_attr(out, 24); wrote = true; }
        if (cur.blink) { append_attr(out, 25); wrote = true; }
        if (cur.inverted) { append_attr(out, 27); wrote = true; }
        if (cur.strikethrough) { append_attr(out, 29); wrote = true; }
        if (wrote) {
            Style def;
            cur = def;
        }
    };
    for (int y = 0; y < s.h; ++y) {
        for (int x = 0; x < s.w; ++x) {
            const Cell& c = s.at(x, y);
            emit_style(c.st);
            // encode as utf-8
            uint32_t cp = c.ch;
            char buf[8];
            int n = 0;
            if (cp < 0x80) { buf[n++] = (char)cp; }
            else if (cp < 0x800) { buf[n++] = (char)(0xC0 | (cp >> 6)); buf[n++] = (char)(0x80 | (cp & 0x3F)); }
            else if (cp < 0x10000) {
                buf[n++] = (char)(0xE0 | (cp >> 12));
                buf[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                buf[n++] = (char)(0x80 | (cp & 0x3F));
            } else {
                buf[n++] = (char)(0xF0 | (cp >> 18));
                buf[n++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                buf[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                buf[n++] = (char)(0x80 | (cp & 0x3F));
            }
            out.append(buf, n);
        }
        end_line();
        out += "\r\r\n";
    }
    return out;
}

}  // namespace cl
EOF
echo ok"}

