// simple flexbox-like layout engine
#pragma once
#include "style.h"
#include <memory>
#include <vector>
#include <string>
#include <functional>

namespace cl {

struct Box { int x = 0, y = 0, w = 0, h = 0; };

struct Elem;
using ElemPtr = std::shared_ptr<Elem>;

struct Elem {
    virtual ~Elem() {}
    // natural size
    virtual void measure(int& w, int& h) = 0;
    virtual void render(Screen& s, const Box& b) = 0;
    bool flex_w = false, flex_h = false;   // stretches to the parent's box
    virtual Elem* ptr() { return this; }
};

// distribute `avail` among children with natural sizes; shrink proportionally
std::vector<int> distribute(const std::vector<int>& nat, int avail);

struct TextElem : Elem {
    std::string text;
    Style st;
    TextElem(std::string t, Style s = Style()) : text(std::move(t)), st(s) {}
    void measure(int& w, int& h) override;
    void render(Screen& s, const Box& b) override;
};

struct FillerElem : Elem {
    void measure(int& w, int& h) override { w = 0; h = 0; }
    void render(Screen& s, const Box& b) override { (void)s; (void)b; }
};

struct VBox : Elem {
    std::vector<ElemPtr> children;
    void measure(int& w, int& h) override;
    void render(Screen& s, const Box& b) override;
};

struct HBox : Elem {
    std::vector<ElemPtr> children;
    void measure(int& w, int& h) override;
    void render(Screen& s, const Box& b) override;
};

// a window with a title drawn on the top border
struct WindowElem : Elem {
    ElemPtr inner;
    std::string title;
    Style border_st;
    Style title_st;
    WindowElem(ElemPtr i, std::string t, Style bs = Style(), Style ts = Style())
        : inner(std::move(i)), title(std::move(t)), border_st(bs), title_st(ts) {}
    void measure(int& w, int& h) override;
    void render(Screen& s, const Box& b) override;
};

// centers the child horizontally inside the given box
struct CenterH : Elem {
    ElemPtr child;
    explicit CenterH(ElemPtr c) : child(std::move(c)) { flex_w = true; }
    void measure(int& w, int& h) override;
    void render(Screen& s, const Box& b) override;
};

// draws nothing but occupies a fixed size
struct FixedSpacer : Elem {
    int sw = 0, sh = 0;
    FixedSpacer(int w, int h) : sw(w), sh(h) {}
    void measure(int& w, int& h) override { w = sw; h = sh; }
    void render(Screen& s, const Box& b) override { (void)s; (void)b; }
};

// helper builders
inline ElemPtr text(const std::string& t, Style s = Style()) { return std::make_shared<TextElem>(t, s); }
inline ElemPtr filler() { return std::make_shared<FillerElem>(); }
inline ElemPtr vbox(std::vector<ElemPtr> c) { auto e = std::make_shared<VBox>(); e->children = std::move(c); return e; }
inline ElemPtr hbox(std::vector<ElemPtr> c) { auto e = std::make_shared<HBox>(); e->children = std::move(c); return e; }
inline ElemPtr center_h(ElemPtr c) { return std::make_shared<CenterH>(std::move(c)); }
inline ElemPtr window(ElemPtr inner, const std::string& title, Style bs = Style(), Style ts = Style()) {
    return std::make_shared<WindowElem>(std::move(inner), title, bs, ts);
}

// box drawing characters
struct Border {
    const char* tl; const char* tr; const char* bl; const char* br;
    const char* h; const char* v;
};
Border border_style(const std::string& name);

}  // namespace cl
EOF
echo ok"}

