{"command": "cat > /workspace/src/layout.cpp <<'EOF'
#include "layout.h"
#include <algorithm>
#include <cstdio>

namespace cl {

std::vector<int> distribute(const std::vector<int>& nat, int avail) {
    size_t n = nat.size();
    std::vector<int> out(n, 0);
    if (n == 0) return out;
    long total = 0;
    for (int v : nat) total += v;
    if (avail >= total) {
        // pack left, extra at the end
        long left = avail;
        for (size_t i = 0; i < n; ++i) {
            out[i] = nat[i];
            left -= nat[i];
        }
        if (left > 0) out[n - 1] += (int)left;
        return out;
    }
    // shrink proportionally
    long deficit = total - avail;
    long assigned = 0;
    std::vector<double> frac(n, 0.0);
    for (size_t i = 0; i < n; ++i) {
        if (total <= 0) { out[i] = 0; continue; }
        double d = (double)deficit * nat[i] / (double)total;
        long take = (long)d;
        if (take > nat[i]) take = nat[i];
        out[i] = nat[i] - (int)take;
        assigned += take;
        frac[i] = d - take;
    }
    long rem = deficit - assigned;
    // distribute remaining deficit to children with the largest fractional part
    while (rem > 0) {
        int best = -1;
        double bf = -1.0;
        for (size_t i = 0; i < n; ++i) {
            if (out[i] <= 0) continue;
            if (frac[i] > bf) { bf = frac[i]; best = (int)i; }
        }
        if (best < 0) break;
        out[best] -= 1;
        frac[best] = -1.0;
        --rem;
    }
    return out;
}

void TextElem::measure(int& w, int& h) { w = (int)text.size(); h = 1; }
void TextElem::render(Screen& s, const Box& b) {
    int n = std::min((int)text.size(), b.w);
    for (int i = 0; i < n; ++i) {
        uint32_t cp = (unsigned char)text[i];
        // decode utf-8
        if ((text[i] & 0x80) == 0) {
            s.put(b.x + i, b.y, cp, st);
        } else {
            // multi-byte: decode
            size_t len = 1;
            unsigned char c0 = text[i];
            if ((c0 & 0xE0) == 0xC0) len = 2;
            else if ((c0 & 0xF0) == 0xE0) len = 3;
            else if ((c0 & 0xF8) == 0xF0) len = 4;
            if (i + (int)len > (int)text.size()) len = 1;
            uint32_t cp2 = 0;
            if (len == 1) cp2 = c0;
            else if (len == 2) cp2 = ((c0 & 0x1F) << 6) | (text[i+1] & 0x3F);
            else if (len == 3) cp2 = ((c0 & 0x0F) << 12) | ((text[i+1] & 0x3F) << 6) | (text[i+2] & 0x3F);
            else cp2 = ((c0 & 0x07) << 18) | ((text[i+1] & 0x3F) << 12) | ((text[i+2] & 0x3F) << 6) | (text[i+3] & 0x3F);
            int cw = char_width(cp2);
            s.put(b.x + i, b.y, cp2, st);
            for (int k = 1; k < cw && i + k < b.w; ++k) {
                s.put(b.x + i + k, b.y, 0, st);  // zero width marker
            }
            i += (len - 1);
            // note: we advance one cell for the glyph; extra width is ignored
        }
    }
}

void VBox::measure(int& w, int& h) {
    w = 0; h = 0;
    for (auto& c : children) {
        int cw = 0, ch = 0;
        c->measure(cw, ch);
        w = std::max(w, cw);
        h += ch;
    }
}
void VBox::render(Screen& s, const Box& b) {
    std::vector<int> nat;
    for (auto& c : children) {
        int cw = 0, ch = 0;
        c->measure(cw, ch);
        nat.push_back(ch);
    }
    std::vector<int> hs = distribute(nat, b.h);
    int y = b.y;
    for (size_t i = 0; i < children.size(); ++i) {
        Box cb{b.x, y, b.w, hs[i]};
        children[i]->render(s, cb);
        y += hs[i];
    }
}

void HBox::measure(int& w, int& h) {
    w = 0; h = 0;
    for (auto& c : children) {
        int cw = 0, ch = 0;
        c->measure(cw, ch);
        w += cw;
        h = std::max(h, ch);
    }
}
void HBox::render(Screen& s, const Box& b) {
    std::vector<int> nat;
    for (auto& c : children) {
        int cw = 0, ch = 0;
        c->measure(cw, ch);
        nat.push_back(cw);
    }
    std::vector<int> ws = distribute(nat, b.w);
    int x = b.x;
    for (size_t i = 0; i < children.size(); ++i) {
        Box cb{x, b.y, ws[i], b.h};
        children[i]->render(s, cb);
        x += ws[i];
    }
}

void WindowElem::measure(int& w, int& h) {
    int iw = 0, ih = 0;
    inner->measure(iw, ih);
    w = iw + 2;
    h = ih + 2;
}
void WindowElem::render(Screen& s, const Box& b) {
    Style st = border_st;
    // top border
    s.put(b.x, b.y, 0x256D, st);   // ╭
    for (int i = 1; i < b.w - 1; ++i) s.put(b.x + i, b.y, 0x2500, st);
    s.put(b.x + b.w - 1, b.y, 0x256E, st);   // ╮
    // sides
    for (int j = 1; j < b.h - 1; ++j) {
        s.put(b.x, b.y + j, 0x2502, st);
        s.put(b.x + b.w - 1, b.y + j, 0x2502, st);
    }
    // bottom
    s.put(b.x, b.y + b.h - 1, 0x2570, st);
    for (int i = 1; i < b.w - 1; ++i) s.put(b.x + i, b.y + b.h - 1, 0x2500, st);
    s.put(b.x + b.w - 1, b.y + b.h - 1, 0x256F, st);
    // title
    if (!title.empty() && b.w > (int)title.size() + 2) {
        int tx = b.x + 1;
        for (size_t i = 0; i < title.size(); ++i) s.put(tx + (int)i, b.y, (unsigned char)title[i], title_st);
    }
    // inner
    Box ib{b.x + 1, b.y + 1, std::max(0, b.w - 2), std::max(0, b.h - 2)};
    inner->render(s, ib);
}

void CenterH::measure(int& w, int& h) {
    child->measure(w, h);
}
void CenterH::render(Screen& s, const Box& b) {
    int cw = 0, ch = 0;
    child->measure(cw, ch);
    int off = 0;
    if (cw < b.w) off = (b.w - cw) / 2;
    Box cb{b.x + off, b.y, std::min(cw, b.w), std::min(ch, b.h)};
    child->render(s, cb);
}

Border border_style(const std::string& name) {
    if (name == "heavy") return {"┏", "┓", "┗", "┛", "━", "┃"};
    if (name == "double") return {"╔", "╗", "╚", "╝", "═", "║"};
    if (name == "rounded") return {"╭", "╮", "╰", "╯", "─", "│"};
    if (name == "dashed") return {"┌", "┐", "└", "┘", "╌", "╎"};
    if (name == "empty") return {" ", " ", " ", " ", " ", " "};
    return {"┌", "┐", "└", "┘", "─", "│"};
}

}  // namespace cl
EOF
echo ok"}

