cat > /workspace/src/config.cpp <<'EOF'
#include "config.h"
#include <fstream>
#include <sstream>
#include <cctype>
#include <cstdlib>
#include <algorithm>

namespace cl {

static std::string trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && (s[a] == ' ' || s[a] == '\t' || s[a] == '\r')) ++a;
    while (b > a && (s[b-1] == ' ' || s[b-1] == '\t' || s[b-1] == '\r')) --b;
    return s.substr(a, b - a);
}

static bool parse_color_spec(const std::string& spec, ThemeColor& out) {
    std::string s = trim(spec);
    out.spec = s;
    std::string low = s;
    std::transform(low.begin(), low.end(), low.begin(), ::tolower);
    if (low == "default" || low.empty()) { out.is_default_color = true; return true; }
    auto paren = [&](const std::string& name, std::string& arg) {
        if (low.rfind(name, 0) == 0 && low.size() > name.size() && low[name.size()] == '(' && low[low.size()-1] == ')') {
            arg = s.substr(name.size()+1, s.size()-name.size()-2);
            return true;
        }
        return false;
    };
    std::string arg;
    if (paren("ansi16", arg)) {
        out.ansi16 = true;
        static const char* names[16] = {"black","maroon","green","olive","navy","purple","teal","silver",
                                        "gray","red","lime","yellow","blue","fuchsia","aqua","white"};
        std::string la = arg; std::transform(la.begin(), la.end(), la.begin(), ::tolower);
        bool found = false;
        for (int i = 0; i < 16; ++i) if (la == names[i]) { out.v = i; found = true; break; }
        if (!found) {
            static const char* names2[16] = {"black","red","green","yellow","blue","magenta","cyan","white",
                                             "gray","brightred","brightgreen","brightyellow","brightblue","brightmagenta","brightcyan","brightblack"};
            for (int i = 0; i < 16; ++i) if (la == names2[i]) { out.v = i; found = true; break; }
        }
        if (!found) { out.v = atoi(arg.c_str()); }
        if (out.v < 0 || out.v > 15) out.v = 7;
        return true;
    }
    if (paren("ansi256", arg)) { out.ansi256 = true; out.v = atoi(arg.c_str()); if (out.v < 0 || out.v > 255) out.v = 7; return true; }
    if (paren("rgb", arg) || paren("rgba", arg)) {
        int vals[4] = {0,0,0,255};
        int n = 0; size_t i = 0;
        while (i < arg.size() && n < 4) {
            while (i < arg.size() && (arg[i]==' '||arg[i]==',')) ++i;
            std::string num;
            while (i < arg.size() && isdigit((unsigned char)arg[i])) { num += arg[i]; ++i; }
            if (!num.empty()) vals[n++] = atoi(num.c_str());
            else break;
            while (i < arg.size() && (arg[i]==' '||arg[i]==',')) ++i;
        }
        out.rgb = true; out.r = vals[0]; out.g = vals[1]; out.b = vals[2];
        if (out.r < 0) out.r = 0; if (out.r > 255) out.r = 255;
        if (out.g < 0) out.g = 0; if (out.g > 255) out.g = 255;
        if (out.b < 0) out.b = 0; if (out.b > 255) out.b = 255;
        return true;
    }
    if (!s.empty() && s[0] == '#' && s.size() >= 7) {
        auto hx = [](char c) -> int {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return c - 'a' + 10;
            if (c >= 'A' && c <= 'F') return c - 'A' + 10;
            return 0;
        };
        out.rgb = true;
        out.r = hx(s[1]) * 16 + hx(s[2]);
        out.g = hx(s[3]) * 16 + hx(s[4]);
        out.b = hx(s[5]) * 16 + hx(s[6]);
        return true;
    }
    // unknown: treat as default
    out.is_default_color = true;
    return false;
}

bool parse_config(const std::string& path, Config& cfg, std::string* err) {
    std::ifstream f(path);
    if (!f.good()) {
        if (err) *err = "Failed to open file: " + path;
        return false;
    }
    std::string line;
    std::string section;
    while (std::getline(f, line)) {
        std::string t = trim(line);
        if (t.empty() || t[0] == '#' || t[0] == ';') continue;
        if (t[0] == '[') {
            size_t e = t.find(']');
            if (e != std::string::npos) section = trim(t.substr(1, e - 1));
            continue;
        }
        size_t eq = t.find('=');
        if (eq == std::string::npos) continue;
        std::string key = trim(t.substr(0, eq));
        std::string val = trim(t.substr(eq + 1));
        if (section.empty()) {
            if (key == "log-dir-path") cfg.log_dir_path = val;
            else if (key == "log-filename-format" || key == "log-name-format") cfg.log_name_format = val;
            else if (key == "sunday-start") cfg.sunday_start = (val == "true" || val == "1" || val == "yes");
            else if (key == "first-line-section") cfg.first_line_section = (val == "true" || val == "1" || val == "yes");
            else if (key == "password") cfg.password = val;
        } else if (section == "git") {
            if (key == "enable-git-log-repo") cfg.git.enable = (val == "true" || val == "1" || val == "yes");
            else if (key == "ssh-key-path") cfg.git.ssh_key = val;
            else if (key == "ssh-pub-key-path") cfg.git.ssh_pub_key = val;
            else if (key == "repo-root") cfg.git.repo_root = val;
            else if (key == "remote-name") cfg.git.remote_name = val;
            else if (key == "main-branch-name") cfg.git.main_branch = val;
        } else if (section == "calendar-events") {
            if (key == "recent-events-window") cfg.recent_events_window = atoi(val.c_str());
        } else if (section.rfind("calendar-events.", 0) == 0) {
            // calendar-events.<group>.<index>
            std::string rest = section.substr(strlen("calendar-events."));
            size_t dot = rest.rfind('.');
            if (dot != std::string::npos) {
                CalendarEvent ev;
                ev.group = rest.substr(0, dot);
                if (key == "name") ev.name = val;
                else if (key == "date") {
                    // DD.MM (optional trailing dot)
                    std::string d = val;
                    if (!d.empty() && d.back() == '.') d.pop_back();
                    size_t p = d.find('.');
                    if (p != std::string::npos) {
                        ev.day = atoi(d.substr(0, p).c_str());
                        ev.month = atoi(d.substr(p + 1).c_str());
                    }
                }
                bool replaced = false;
                for (auto& e : cfg.events) {
                    if (e.group == ev.group && e.name.empty()) { e = ev; replaced = true; break; }
                }
                if (!replaced) cfg.events.push_back(ev);
            }
        } else if (section.rfind("view.", 0) == 0) {
            // theme section: view.<view>.theme[.component]
            std::string rest = section.substr(strlen("view."));
            std::string full = rest + "." + key;
            if (key == "border" || key.rfind("border", 0) == 0 || key.find(".border") != std::string::npos) {
                cfg.theme_border[full] = val;
                // also register as the plain component name
                size_t d2 = full.rfind(".border");
                if (d2 != std::string::npos) cfg.theme_border[full.substr(0, d2)] = val;
            } else {
                ThemeColor c;
                parse_color_spec(val, c);
                cfg.theme[full] = c;
            }
        }
    }
    return true;
}

}  // namespace cl
