    store.year = year;
    char sub[32];
    snprintf(sub, sizeof(sub), "y%d", year);
    std::string dir = store.dir + "/" + sub;
    DIR* dp = opendir(dir.c_str());
    if (!dp) return;
    std::vector<std::string> files;
    struct dirent* de;
    while ((de = readdir(dp)) != nullptr) {
        std::string n = de->d_name;
        if (n == "." || n == "..") continue;
        files.push_back(n);
    }
    closedir(dp);
    std::sort(files.begin(), files.end());
    for (auto& n : files) {
        Date d;
        if (!match_format(store.name_format, n, &d)) continue;
        std::string path = dir + "/" + n;
        FILE* f = fopen(path.c_str(), "rb");
        if (!f) continue;
        LogEntry e;
        e.date = d;
        e.path = path;
        std::string content;
        char buf[4096];
        size_t r;
        while ((r = fread(buf, 1, sizeof(buf), f)) > 0) content.append(buf, r);
        fclose(f);
        // split lines
        size_t pos = 0;
        while (pos <= content.size()) {
            size_t nl = content.find('\n', pos);
            std::string line;
            if (nl == std::string::npos) {
                line = content.substr(pos);
                if (!line.empty()) e.lines.push_back(line);
                break;
            }
            line = content.substr(pos, nl - pos);
            if (!line.empty() && line.back() == '\r') line.pop_back();
            e.lines.push_back(line);
            pos = nl + 1;
        }
        parse_content(e, store.first_line_section);
        store.entries[d] = e;
        if (out_dates) out_dates->push_back(d);
        for (auto& s : e.section_order) {
            store.section_dates[s].insert(d);
            for (auto& t : e.section_tag_set[s]) {
                store.section_tag_dates[s][t].insert(d);
            }
        }
        for (auto& t : e.all_tags) store.tag_dates[t].insert(d);
    }
