void LogStore::set_year(int y) {
    if (y == year && !entries.empty()) return;
    scan_dir(*this, y, nullptr);
}

int LogStore::count_for_year(int y) const {
    char sub[32];
    snprintf(sub, sizeof(sub), "y%d", y);
    std::string dir = this->dir + "/" + sub;
    DIR* dp = opendir(dir.c_str());
    if (!dp) return 0;
    int n = 0;
    struct dirent* de;
    while ((de = readdir(dp)) != nullptr) {
        std::string name = de->d_name;
        if (name == "." || name == "..") continue;
        Date d;
        if (match_format(name_format, name, &d)) ++n;
    }
    closedir(dp);
    return n;
}

bool LogStore::has_log(const Date& d) const {
    return entries.find(d) != entries.end();
}
const LogEntry* LogStore::entry(const Date& d) const {
    auto it = entries.find(d);
    return it == entries.end() ? nullptr : &it->second;
}

std::set<Date> LogStore::filter_dates(const std::string& section, const std::string& tag) const {
    if (!section.empty()) {
        auto it = section_dates.find(section);
        if (it == section_dates.end()) return {};
        if (tag.empty()) return it->second;
        auto sit = section_tag_dates.find(section);
        if (sit == section_tag_dates.end()) return {};
        auto tit = sit->second.find(tag);
        if (tit == sit->second.end()) return {};
        return tit->second;
    }
    if (!tag.empty()) {
        auto it = tag_dates.find(tag);
        if (it == tag_dates.end()) return {};
        return it->second;
    }
    return {};
}

std::vector<std::string> LogStore::sections_sorted() const {
    std::vector<std::string> out;
    for (auto& kv : section_dates) if (!kv.second.empty()) out.push_back(kv.first);
    // <root section> first, then alphabetical
    std::vector<std::string> rest;
    for (auto& s : out) if (s != kRootSection) rest.push_back(s);
    std::sort(rest.begin(), rest.end());
    std::vector<std::string> res;
    if (section_dates.count(kRootSection) && !section_dates.at(kRootSection).empty())
        res.push_back(kRootSection);
    for (auto& s : rest) res.push_back(s);
    return res;
}

std::vector<std::string> LogStore::tags_sorted(const std::string& section) const {
    std::vector<std::string> out;
    if (!section.empty()) {
        auto it = section_tag_dates.find(section);
        if (it != section_tag_dates.end()) {
            for (auto& kv : it->second) if (!kv.second.empty()) out.push_back(kv.first);
        }
    } else {
        for (auto& kv : tag_dates) if (!kv.second.empty()) out.push_back(kv.first);
    }
    std::sort(out.begin(), out.end());
    return out;
}

}  // namespace cl
