static const int kMDays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

int Date::days_in_month() const {
    if (m < 1 || m > 12) return 30;
    if (m == 2 && is_leap()) return 29;
    return kMDays[m];
