Date Date::add_days(int n) const {
    Date r = *this;
    r.d += n;
    while (r.d > r.days_in_month()) {
        r.d -= r.days_in_month();
        r.m += 1;
        if (r.m > 12) { r.m = 1; r.y += 1; }
    }
    while (r.d < 1) {
        r.m -= 1;
        if (r.m < 1) { r.m = 12; r.y -= 1; }
        r.d += r.days_in_month();
    }
    return r;
}

int Date::diff_days(const Date& other) const {
    // serial day numbers
    auto serial = [](const Date& x) -> long {
        long yy = x.y;
        long mm = x.m;
        long dd = x.d;
        yy -= mm <= 2;
        long era = (yy >= 0 ? yy : yy - 399) / 400;
        long yoe = yy - era * 400;
        long doy = (153 * (mm + (mm > 2 ? -3 : 9)) + 2) / 5 + dd - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe;
    };
    return (int)(serial(other) - serial(*this));
}

int Date::weekday(int sunday_start) const {
    // 1970-01-01 was a Thursday
    Date ref; ref.y = 1970; ref.m = 1; ref.d = 1;
    int diff = ref.diff_days(*this);
    int w = ((diff % 7) + 7 + 3) % 7;   // 0 = Thursday -> convert: 1970-01-01 = Thursday(4)
    // w: 0 => Thursday. Monday index: (w + 4) % 7 with Monday=0
    int mon = (w + 4) % 7;
    if (sunday_start) return (mon + 1) % 7;
    return mon;
}

static std::string lower(const std::string& s) {
    std::string r = s;
    for (auto& c : r) c = (char)tolower((unsigned char)c);
    return r;
}

static std::string trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && isspace((unsigned char)s[a])) ++a;
    while (b > a && isspace((unsigned char)s[b-1])) --b;
    return s.substr(a, b - a);
}

// parse a tag line: `* tag name` possibly with (parens) and/or :body
static bool parse_tag_line(const std::string& line, std::string* out) {
    size_t i = 0;
    while (i < line.size() && (line[i] == ' ' || line[i] == '\t')) ++i;
    if (i >= line.size() || line[i] != '*') return false;
    ++i;
    if (i >= line.size() || line[i] != ' ') return false;
    while (i < line.size() && line[i] == ' ') ++i;
    size_t start = i;
    std::string name;
    while (i < line.size()) {
        char c = line[i];
        bool ok = isalnum((unsigned char)c) || c == '-' || c == ' ';
        if (!ok) break;
        name += c;
        ++i;
    }
    // trim trailing spaces
    std::string t = name;
    size_t a = 0, b = t.size();
    while (b > a && t[b-1] == ' ') --b;
    t = t.substr(a, b - a);
    if (t.empty()) return false;
    // optional ( ... )
    std::string rest = line.substr(i);
    std::string r = rest;
    size_t p = 0;
    while (p < r.size() && r[p] == ' ') ++p;
    if (p < r.size() && r[p] == '(') {
        size_t close = r.find(')', p);
        if (close == std::string::npos) return false;
        p = close + 1;
        while (p < r.size() && r[p] == ' ') ++p;
        if (p < r.size() && r[p] == ':') {
            // ok
            p = r.size();
        } else if (p != r.size()) {
            return false;
        }
    } else if (p < r.size() && r[p] == ':') {
        p = r.size();
    } else if (p != r.size()) {
        return false;
    }
    *out = lower(t);
    return true;
}

static bool parse_section_line(const std::string& line, std::string* out) {
    size_t i = 0;
    while (i < line.size() && (line[i] == ' ' || line[i] == '\t')) ++i;
    if (i >= line.size() || line[i] != '#') return false;
    ++i;
    if (i >= line.size() || line[i] != ' ') return false;
    while (i < line.size() && line[i] == ' ') ++i;
    std::string name = line.substr(i);
    name = trim(name);
    if (name.empty()) return false;
    *out = lower(name);
    return true;
}

static void parse_content(LogEntry& e, bool first_line_section) {
    std::string current = kRootSection;
    e.section_order.push_back(current);
    for (size_t i = 0; i < e.lines.size(); ++i) {
        const std::string& line = e.lines[i];
        std::string name;
        bool is_section = parse_section_line(line, &name);
        if (is_section) {
            if (i == 0 && !first_line_section) {
                // ignore the first line as a section
            } else {
                current = name;
                e.section_order.push_back(current);
                e.all_sections.insert(current);
            }
        }
        std::string tag;
        if (parse_tag_line(line, &tag)) {
            e.tags_in_order.push_back(tag);
            e.all_tags.insert(tag);
            e.section_tags[current].push_back(tag);
            e.section_tag_set[current].insert(tag);
        }
    }
}

static bool match_format(const std::string& fmt, const std::string& name, Date* out) {
    // supports %Y, %y, %m, %d and literal characters
    size_t fi = 0, ni = 0;
    int y = 0, m = 0, d = 0;
    bool have_y = false, have_m = false, have_d = false;
    while (fi < fmt.size()) {
        if (fmt[fi] == '%' && fi + 1 < fmt.size()) {
            char c = fmt[fi + 1];
            ++fi;
            int digits = (c == 'Y') ? 4 : (c == 'y' ? 2 : 2);
            if (c != 'Y' && c != 'y' && c != 'm' && c != 'd') {
                // literal %
                if (ni >= name.size() || name[ni] != '%') return false;
                ++ni; ++fi; continue;
            }
            int val = 0, cnt = 0;
            while (ni < name.size() && cnt < digits && isdigit((unsigned char)name[ni])) {
                val = val * 10 + (name[ni] - '0');
                ++ni; ++cnt;
            }
            if (cnt != digits) return false;
            if (c == 'Y') { y = val; have_y = true; }
            else if (c == 'y') { y = 2000 + val; have_y = true; }
            else if (c == 'm') { m = val; have_m = true; }
            else { d = val; have_d = true; }
            ++fi;
        } else {
            if (ni >= name.size() || name[ni] != fmt[fi]) return false;
            ++ni; ++fi;
        }
    }
    if (ni != name.size()) return false;
    if (!have_y || !have_m || !have_d) return false;
    out->y = y; out->m = m; out->d = d;
    return out->valid();
}

void scan_dir(LogStore& store, int year, std::vector<Date>* out_dates) {
    store.entries.clear();
    store.section_dates.clear();
    store.tag_dates.clear();
    store.section_tag_dates.clear();
    store.year = year;
    char sub[32];
    snprintf(sub, sizeof(sub), "y%d", year);
    std::string dir = store.dir + "/" + sub;
    DIR* dp = opendir(dir.c_str());
    if (!dp) return;
    std::vector<std::string> files;
    struct dirent* de;
    while ((de = readdir(dp)) != nullptr) {
        std::string n = de->d_name;
        if (n == "." || n == "..") continue;
        files.push_back(n);
    }
    closedir(dp);
    std::sort(files.begin(), files.end());
    for (auto& n : files) {
        Date d;
        if (!match_format(store.name_format, n, &d)) continue;
        std::string path = dir + "/" + n;
        FILE* f = fopen(path.c_str(), "rb");
        if (!f) continue;
        LogEntry e;
        e.date = d;
        e.path = path;
        std::string content;
        char buf[4096];
        size_t r;
        while ((r = fread(buf, 1, sizeof(buf), f)) > 0) content.append(buf, r);
        fclose(f);
        // split lines
        size_t pos = 0;
        while (pos <= content.size()) {
            size_t nl = content.find('\n', pos);
            std::string line;
            if (nl == std::string::npos) {
                line = content.substr(pos);
                if (!line.empty()) e.lines.push_back(line);
                break;
            }
            line = content.substr(pos, nl - pos);
            if (!line.empty() && line.back() == '\r') line.pop_back();
            e.lines.push_back(line);
            pos = nl + 1;
        }
        parse_content(e, store.first_line_section);
        store.entries[d] = e;
        if (out_dates) out_dates->push_back(d);
        for (auto& s : e.section_order) {
            store.section_dates[s].insert(d);
            for (auto& t : e.section_tag_set[s]) {
                store.section_tag_dates[s][t].insert(d);
            }
        }
        for (auto& t : e.all_tags) store.tag_dates[t].insert(d);
    }
}

