                    ns[4*c+3] = (uint8_t)(gmul(3,a[0]) ^ a[1] ^ a[2] ^ gmul(2,a[3]));
                }
                for (int i = 0; i < 16; ++i) s[i] = ns[i];
            }
            for (int c = 0; c < 4; ++c)
                for (int r = 0; r < 4; ++r) s[4 * c + r] ^= w[4 * rnd + c][r];
        }
        for (int i = 0; i < 16; ++i) out[i] = s[i];
    }
};

