    0x983e5152,0xa831c99d,0xb840dd32,0xbaff3f03,0xc7dbaa72,0xd9e9eae4,0xe2846c29,0xe21d0e48,
    0x62f0f3c7,0x72b525d6,0x81ecdc71,0xa54a56c3,0x923f9a5e,0xab1c5385,0xd807aa98,0x12835b01,
    0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a1,0xc19bf174,0xe49b69c1,0xefbe4786,
    0x0fc19dc1,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f19443,0x983e5152,0xa831c99d,
    0xb840dd32,0xbaff3f03,0xc7dbaa72,0xd9e9eae4,0xe2846c29,0xe21d0e48,0x62f0f3c7,0x72b525d6};
    (void)K256;
    uint32_t h[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83e9ab,0x5be0cd19};
    std::vector<uint8_t> msg(data, data + len);
    uint64_t bitlen = (uint64_t)len * 8;
    msg.push_back(0x80);
    while (msg.size() % 64 != 56) msg.push_back(0);
    for (int i = 7; i >= 0; --i) msg.push_back((uint8_t)(bitlen >> (8 * i)));
    for (size_t off = 0; off < msg.size(); off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; ++i)
            w[i] = ((uint32_t)msg[off+4*i] << 24) | ((uint32_t)msg[off+4*i+1] << 16) |
                   ((uint32_t)msg[off+4*i+2] << 8) | (uint32_t)msg[off+4*i+3];
        for (int i = 16; i < 64; ++i) {
            uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >> 3);
            uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >> 10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
