            uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = hh + S1 + ch + KK[i] + w[i];
            uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
            uint32_t mj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + mj;
            hh=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
        }
        h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=hh;
    }
    for (int i = 0; i < 8; ++i) {
        out[4*i] = (uint8_t)(h[i] >> 24); out[4*i+1] = (uint8_t)(h[i] >> 16);
        out[4*i+2] = (uint8_t)(h[i] >> 8); out[4*i+3] = (uint8_t)h[i];
    }
}

std::string aes_cfb_encrypt(const std::string& key, const std::string& iv, const std::string& plain) {
    Aes aes((const uint8_t*)key.data(), (int)key.size());
    uint8_t shift[16];
    for (int i = 0; i < 16; ++i) shift[i] = (uint8_t)iv[i];
    std::string out;
    out.reserve(plain.size());
    size_t i = 0;
    while (i < plain.size()) {
        uint8_t ks[16];
        aes.encrypt_block(shift, ks);
        size_t n = std::min((size_t)16, plain.size() - i);
        std::string chunk;
        for (size_t j = 0; j < n; ++j) {
            uint8_t c = (uint8_t)plain[i + j] ^ ks[j];
            chunk += (char)c;
            out += (char)c;
        }
        // shift register: shift left by n, append ciphertext
        if (n == 16) {
            for (int j = 0; j < 16; ++j) shift[j] = (uint8_t)chunk[j];
        } else {
            for (int j = 0; j < 16 - (int)n; ++j) shift[j] = shift[j + n];
            for (size_t j = 0; j < n; ++j) shift[16 - n + j] = (uint8_t)chunk[j];
        }
        i += n;
    }
    return out;
}

std::string aes_cfb_decrypt(const std::string& key, const std::string& iv, const std::string& ct) {
    Aes aes((const uint8_t*)key.data(), (int)key.size());
    uint8_t shift[16];
    for (int i = 0; i < 16; ++i) shift[i] = (uint8_t)iv[i];
    std::string out;
    out.reserve(ct.size());
    size_t i = 0;
    while (i < ct.size()) {
        uint8_t ks[16];
        aes.encrypt_block(shift, ks);
        size_t n = std::min((size_t)16, ct.size() - i);
        for (size_t j = 0; j < n; ++j) out += (char)((uint8_t)ct[i + j] ^ ks[j]);
        if (n == 16) {
            for (int j = 0; j < 16; ++j) shift[j] = (uint8_t)ct[i + j];
        } else {
            for (int j = 0; j < 16 - (int)n; ++j) shift[j] = shift[j + n];
            for (size_t j = 0; j < n; ++j) shift[16 - n + j] = (uint8_t)ct[i + j];
        }
        i += n;
    }
    return out;
}

std::string derive_key(const std::string& password) {
    uint8_t d[32];
    sha256((const uint8_t*)password.data(), password.size(), d);
    return std::string((char*)d, 32);
}

}  // namespace cl
