namespace cl {

static std::string fmt2(int v) { char b[16]; snprintf(b, sizeof(b), "%02d", v); return b; }
static std::string fmt(int v) { char b[32]; snprintf(b, sizeof(b), "%d", v); return b; }

// ---------- helpers ----------
static std::string home_expand(const std::string& p) {
    if (p.empty()) return p;
    if (p[0] == '~') {
        const char* h = getenv("HOME");
        std::string hp = h ? h : "";
        return hp + p.substr(1);
    }
    return p;
}

static bool file_exists(const std::string& p) {
    struct stat st;
    return stat(p.c_str(), &st) == 0;
}

static bool read_file(const std::string& path, std::string* out) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return false;
    out->clear();
    char buf[8192];
    size_t r;
    while ((r = fread(buf, 1, sizeof(buf), f)) > 0) out->append(buf, r);
    fclose(f);
    return true;
}

static bool write_file(const std::string& path, const std::string& data) {
    FILE* f = fopen(path.c_str(), "wb");
    if (!f) return false;
    fwrite(data.data(), 1, data.size(), f);
    fclose(f);
    return true;
}

static std::vector<std::string> split_lines(const std::string& s) {
    std::vector<std::string> out;
    size_t pos = 0;
    while (pos <= s.size()) {
        size_t nl = s.find('\n', pos);
        if (nl == std::string::npos) {
            std::string line = s.substr(pos);
            if (!line.empty()) out.push_back(line);
            break;
        }
        std::string line = s.substr(pos, nl - pos);
        if (!line.empty() && line.back() == '\r') line.pop_back();
        out.push_back(line);
        pos = nl + 1;
    }
    return out;
}

static std::string join_lines(const std::vector<std::string>& lines) {
    std::string out;
    for (auto& l : lines) { out += l; out += "\n"; }
    return out;
}

// ---------- date helpers ----------
std::string date_str_full(const Date& d) {   // DD. MM. YYYY.
    return fmt2(d.d) + ". " + fmt2(d.m) + ". " + fmt(d.y) + ".";
}
std::string date_str_short(const Date& d) {  // DD. MM. YY.
    return fmt2(d.d) + ". " + fmt2(d.m) + ". " + fmt2(d.y % 100) + ".";
}

// ---------- markdown ----------
std::vector<MdLine> render_markdown(const std::vector<std::string>& lines, const AppState& st) {
    std::vector<MdLine> out;
    bool in_code = false;
    for (auto& raw : lines) {
        std::string l = raw;
        // strip \r
        if (!l.empty() && l.back() == '\r') l.pop_back();
        Style s;
        s.dim = true;
        if (in_code) {
            Style cs; cs.dim = true; cs.fg = st.md_code;
            out.push_back({l, cs});
            if (l.size() >= 3 && l.compare(0, 3, "```") == 0) in_code = false;
            continue;
        }
        if (l.size() >= 3 && l.compare(0, 3, "```") == 0) {
            Style cs; cs.dim = true; cs.fg = st.md_code;
            out.push_back({l, cs});
            in_code = true;
            continue;
        }
        int level = 0;
        while (level < (int)l.size() && l[level] == '#') ++level;
        if (level >= 1 && level <= 6 && level < (int)l.size() && l[level] == ' ') {
            Style hs; hs.dim = true; hs.bold = true; hs.fg = st.md_header[level-1];
            out.push_back({l, hs});
            continue;
        }
        // list markers
        size_t p = 0;
        while (p < l.size() && (l[p] == ' ' || l[p] == '\t')) ++p;
        if (p + 1 < l.size() && (l[p] == '*' || l[p] == '-' || l[p] == '+') && l[p+1] == ' ') {
            Style ls; ls.dim = true; ls.bold = true; ls.fg = st.md_list;
            Style rest; rest.dim = true;
            out.push_back({l.substr(0, p + 2), ls});
            out.push_back({l.substr(p + 2), rest});
            continue;
        }
        if (p + 1 < l.size() && l[p] == '>' && l[p+1] == ' ') {
            Style qs; qs.dim = true; qs.fg = st.md_quote;
            Style rest; rest.dim = true;
            out.push_back({l.substr(0, p + 2), qs});
            out.push_back({l.substr(p + 2), rest});
            continue;
        }
        out.push_back({l, s});
    }
    return out;
}

// ---------- scratchpads ----------
void scan_scratchpads(AppState& st) {
    st.scratchpads.clear();
    std::string dir = st.logs.dir + "/scratchpads";
    DIR* dp = opendir(dir.c_str());
    if (!dp) return;
    struct dirent* de;
    std::vector<Scratchpad> v;
    while ((de = readdir(dp)) != nullptr) {
        std::string n = de->d_name;
        if (n == "." || n == "..") continue;
        if (n.size() < 3 || n.compare(n.size() - 3, 3, ".md") != 0) continue;
        Scratchpad sp;
        sp.name = n;
        sp.path = dir + "/" + n;
        struct stat sb;
        if (stat(sp.path.c_str(), &sb) == 0) sp.mtime = sb.st_mtime;
        v.push_back(sp);
    }
    closedir(dp);
    std::sort(v.begin(), v.end(), [](const Scratchpad& a, const Scratchpad& b) {
        if (a.mtime != b.mtime) return a.mtime > b.mtime;
        return a.name > b.name;
    });
    st.scratchpads = v;
    if (st.scratch_idx >= (int)st.scratchpads.size()) st.scratch_idx = 0;
}

// ---------- app state ----------
void AppState::reload_menus() {
    sections = logs.sections_sorted();
    tags = logs.tags_sorted(selected_section());
    if (section_idx > (int)sections.size()) section_idx = (int)sections.size();
    if (tag_idx > (int)tags.size()) tag_idx = (int)tags.size();
}

std::set<Date> AppState::log_dates() const {
    std::set<Date> out;
    for (auto& kv : logs.entries) out.insert(kv.first);
    return out;
}

std::set<Date> AppState::filtered_dates() const {
    return logs.filter_dates(selected_section(), selected_tag());
}

// ---------- events ----------
struct EventInfo {
    std::string group;
    std::string name;
    int month, day;
    Date date;      // occurrence in the displayed year
    int diff;       // date - today
};

static std::vector<EventInfo> event_infos(const AppState& st) {
    std::vector<EventInfo> out;
    for (auto& ev : st.cfg.events) {
        EventInfo i;
        i.group = ev.group;
        i.name = ev.name;
        i.month = ev.month;
        i.day = ev.day;
        Date d;
        d.y = st.year;
        d.m = ev.month;
        d.d = ev.day;
        if (!d.valid()) continue;
        i.date = d;
        i.diff = st.today.diff_days(d);
        out.push_back(i);
    }
    return out;
}

// groups kept in the order they appear in the config, max 4 per group,
// keeping the earliest dates of the year
static std::vector<EventInfo> listed_events(const AppState& st) {
    auto infos = event_infos(st);
    std::map<std::string, std::vector<EventInfo>> by_group;
    for (auto& i : infos) by_group[i.group].push_back(i);
    std::vector<EventInfo> out;
    for (auto& kv : by_group) {
        std::vector<EventInfo> g = kv.second;
        // keep in config order, limited to 4
        if ((int)g.size() > 4) {
            std::vector<EventInfo> sorted = g;
            std::stable_sort(sorted.begin(), sorted.end(), [](const EventInfo& a, const EventInfo& b) {
                if (a.month != b.month) return a.month < b.month;
                return a.day < b.day;
            });
            std::set<int> keep;
            for (int i = 0; i < 4; ++i) keep.insert(sorted[i].month * 100 + sorted[i].day);
            std::vector<EventInfo> filtered;
            for (auto& e : g) if (keep.count(e.month * 100 + e.day)) filtered.push_back(e);
            g = filtered;
        }
        for (auto& e : g) {
            int ad = e.diff < 0 ? -e.diff : e.diff;
            if (ad < st.cfg.recent_events_window) out.push_back(e);
        }
    }
    return out;
}

// ---------- drawing helpers ----------
static void draw_text(Screen& s, int x, int y, const std::string& t, const Style& st) {
    for (size_t i = 0; i < t.size(); ++i) {
        uint32_t cp = (unsigned char)t[i];
        if ((t[i] & 0x80) == 0) {
            s.put(x + (int)i, y, cp, st);
        } else {
            size_t len = 1;
            unsigned char c0 = t[i];
            if ((c0 & 0xE0) == 0xC0) len = 2;
            else if ((c0 & 0xF0) == 0xE0) len = 3;
            else if ((c0 & 0xF8) == 0xF0) len = 4;
            if (i + len > t.size()) len = 1;
            uint32_t cp2 = c0;
            if (len == 2) cp2 = ((c0 & 0x1F) << 6) | (t[i+1] & 0x3F);
            else if (len == 3) cp2 = ((c0 & 0x0F) << 12) | ((t[i+1] & 0x3F) << 6) | (t[i+2] & 0x3F);
            else if (len == 4) cp2 = ((c0 & 0x07) << 18) | ((t[i+1] & 0x3F) << 12) | ((t[i+2] & 0x3F) << 6) | (t[i+3] & 0x3F);
            int cw = char_width(cp2);
            s.put(x + (int)i, y, cp2, st);
            for (int k = 1; k < cw; ++k) s.put(x + (int)i + k, y, 0, st);
            i += len - 1;
        }
    }
}

static void draw_box(Screen& s, const Box& b, const Style& st) {
    if (b.w < 2 || b.h < 2) return;
    s.put(b.x, b.y, 0x256D, st);
    for (int i = 1; i < b.w - 1; ++i) s.put(b.x + i, b.y, 0x2500, st);
    s.put(b.x + b.w - 1, b.y, 0x256E, st);
    for (int j = 1; j < b.h - 1; ++j) {
        s.put(b.x, b.y + j, 0x2502, st);
        s.put(b.x + b.w - 1, b.y + j, 0x2502, st);
    }
    s.put(b.x, b.y + b.h - 1, 0x2570, st);
    for (int i = 1; i < b.w - 1; ++i) s.put(b.x + i, b.y + b.h - 1, 0x2500, st);
    s.put(b.x + b.w - 1, b.y + b.h - 1, 0x256F, st);
}

// draw a bordered box with junction merging against what is already drawn
static void draw_box_merge(Screen& s, const Box& b, const Style& st) {
    if (b.w < 1 || b.h < 1) return;
    auto vchar = [&](int x, int y) {
        uint32_t c = 0x2502;
        // left neighbour outside
        if (x - 1 >= 0) {
            uint32_t l = s.at(x - 1, y).ch;
            if (l == 0x2500 || l == 0x252C || l == 0x2534 || l == 0x253C) c = 0x2524;  // ┤
        }
        if (x + 1 < s.w) {
            uint32_t r = s.at(x + 1, y).ch;
            if (r == 0x2500 || r == 0x252C || r == 0x2534 || r == 0x253C) c = 0x251C;  // ├
        }
        s.put(x, y, c, st);
    };
    auto hchar = [&](int x, int y) {
        uint32_t c = 0x2500;
        if (y - 1 >= 0) {
            uint32_t u = s.at(x, y - 1).ch;
            if (u == 0x2502 || u == 0x251C || u == 0x2524 || u == 0x253C) c = 0x2534;  // ┴
        }
        if (y + 1 < s.h) {
            uint32_t d = s.at(x, y + 1).ch;
            if (d == 0x2502 || d == 0x251C || d == 0x2524 || d == 0x253C) c = 0x252C;  // ┬
        }
        s.put(x, y, c, st);
    };
    s.put(b.x, b.y, 0x256D, st);
    for (int i = 1; i < b.w - 1; ++i) hchar(b.x + i, b.y);
    if (b.w > 1) s.put(b.x + b.w - 1, b.y, 0x256E, st);
    for (int j = 1; j < b.h - 1; ++j) {
        vchar(b.x, b.y + j);
        if (b.w > 1) vchar(b.x + b.w - 1, b.y + j);
    }
    if (b.h > 1) {
        s.put(b.x, b.y + b.h - 1, 0x2570, st);
        for (int i = 1; i < b.w - 1; ++i) hchar(b.x + i, b.y + b.h - 1);
        if (b.w > 1) s.put(b.x + b.w - 1, b.y + b.h - 1, 0x256F, st);
    }
}

// ---------- title ----------
static std::string title_text(const AppState& st) {
    std::string ev;
    for (auto& e : listed_events(st)) {
        if (e.diff == 0) { ev = e.group + " - " + e.name; break; }
    }
    std::string t = "Today is: " + date_str_full(st.today) + " " + ev + " | There are " +
                    fmt(st.logs.count_for_year(st.year)) + " log entries for year " + fmt(st.year) + ".";
    return t;
}

// ---------- menus ----------
static void draw_menu(Screen& s, const Box& b, const std::string& title,
                      const std::vector<std::string>& names,
                      const std::vector<int>& counts,
                      int sel, bool focused, const Style& border_st) {
    draw_box(s, b, border_st);
    // title
    if (!title.empty()) {
        Style ts = border_st;
        draw_text(s, b.x + 1, b.y, title, ts);
    }
    int inner_x = b.x + 1, inner_w = std::max(0, b.w - 2);
    int rows = std::max(0, b.h - 2);
    int y = b.y + 1;
    int total = (int)names.size() + 1;
    for (int i = 0; i < total && i < rows; ++i) {
        Style st;   // default
        if (focused && i == sel) { st.bold = true; st.inverted = true; }
        else if (!focused && i == sel) { st.bold = true; st.dim = true; }
        std::string line;
        char pre = (i == sel) ? '>' : ' ';
        if (i == 0) {
            line = std::string(1, pre) + " <select none>";
        } else {
            char buf[32];
            snprintf(buf, sizeof(buf), "%4d", counts[i - 1]);
            line = std::string(1, pre) + buf + " │ " + names[i - 1];
        }
        if ((int)line.size() > inner_w) line = line.substr(0, inner_w);
        draw_text(s, inner_x, y + i, line, st);
    }
}

// ---------- events list ----------
static void draw_events(Screen& s, const Box& b, const AppState& st, const Style& border_st) {
    draw_box(s, b, border_st);
    auto evs = listed_events(st);
    std::string title = "Recent & upcoming events (" + fmt((int)evs.size()) + ")";
    draw_text(s, b.x + 1, b.y, title, border_st);
    int inner_w = std::max(0, b.w - 2);
    int y = b.y + 1;
    int rows = std::max(0, b.h - 2);
    std::string last_group;
    for (auto& e : evs) {
        if (rows <= 0) break;
        if (e.group != last_group) {
            Style hs; hs.bold = true; hs.underline = true;
            std::string g = e.group;
            if ((int)g.size() > inner_w) g = g.substr(0, inner_w);
            draw_text(s, b.x + 1, y, g, hs);
            ++y; --rows;
            last_group = e.group;
        }
        if (rows <= 0) break;
        std::string rel;
        if (e.diff == 0) rel = "today";
        else if (e.diff > 0) rel = "in " + fmt(e.diff) + " days";
        else rel = fmt(-e.diff) + " days ago";
        char db[32];
        snprintf(db, sizeof(db), "%02d.%02d.", e.month, e.day);
        std::string line = " - " + e.name + " " + db + " (" + rel + ")";
        if ((int)line.size() > inner_w) line = line.substr(0, inner_w);
        Style es; es.dim = true;
        draw_text(s, b.x + 1, y, line, es);
        ++y; --rows;
    }
}

// ---------- calendar ----------
static const char* kMonthNames[12] = {"January","February","March","April","May","June",
                                      "July","August","September","October","November","December"};

static int weeks_in_month(const Date& d, bool sunday_start) {
    Date first; first.y = d.y; first.m = d.m; first.d = 1;
    int off = first.weekday(sunday_start);
    int total = off + d.days_in_month();
    return (total + 6) / 7;
}

static void draw_month(Screen& s, const Box& b, int year, int month, const AppState& st,
                       const Style& border_st) {
    draw_box(s, b, border_st);
    draw_text(s, b.x + 1, b.y, kMonthNames[month], border_st);
    bool ss = st.logs.sunday_start;
    Date first; first.y = year; first.m = month + 1; first.d = 1;
    int off = first.weekday(ss);
    int ndays = first.days_in_month();
    int nweeks = weeks_in_month(first, ss);
    // weekday header
    static const char* mon[7] = {"M","T","W","T","F","S","S"};
    static const char* sun[7] = {"S","M","T","W","T","F","S"};
    Style hs; hs.underline = true;
    std::string hdr;
    for (int i = 0; i < 7; ++i) { hdr += " "; hdr += (ss ? sun[i] : mon[i]); hdr += " "; }
    if ((int)hdr.size() > b.w - 2) hdr = hdr.substr(0, b.w - 2);
    draw_text(s, b.x + 1, b.y + 1, hdr, hs);
    auto filtered = st.filtered_dates();
    auto logs_set = st.log_dates();
    auto today_events = std::set<Date>();
    for (auto& e : st.cfg.events) {
        Date d; d.y = st.year; d.m = e.month; d.d = e.day;
        if (d.valid()) today_events.insert(d);
    }
    Style base; base.dim = true;    // empty date
    int y = b.y + 2;
    for (int w = 0; w < nweeks; ++w) {
        if (y >= b.y + b.h - 1) break;
        std::string row;
        for (int i = 0; i < 7; ++i) {
            int daynum = w * 7 + i - off + 1;
            char buf[8];
            if (daynum < 1 || daynum > ndays) snprintf(buf, sizeof(buf), "  ");
            else snprintf(buf, sizeof(buf), "%2d", daynum);
            row += std::string(buf) + " ";
        }
        // draw base then override numbers
        if ((int)row.size() > b.w - 2) row = row.substr(0, b.w - 2);
        draw_text(s, b.x + 1, y, row, base);
        for (int i = 0; i < 7; ++i) {
            int daynum = w * 7 + i - off + 1;
            if (daynum < 1 || daynum > ndays) continue;
            Date d; d.y = year; d.m = month + 1; d.d = daynum;
            Style stl;
            bool is_log = logs_set.count(d) > 0;
            bool is_weekend = d.weekday(ss) == 5 || d.weekday(ss) == 6;
            bool is_today = d == st.today;
            bool is_filter = filtered.count(d) > 0;
            bool is_event = today_events.count(d) > 0;
            bool has_underline = false;
            if (is_filter) { stl.fg = st.col_filter; stl.underline = true; }
            else if (is_today) { stl.fg = st.col_today; stl.dim = true; }
            else if (is_log) { stl.underline = true; has_underline = true; }
            else if (is_event) { stl.fg = st.col_event; stl.dim = true; }
            else if (is_weekend) { stl.fg = st.col_weekend; stl.dim = true; }
            else stl.dim = true;
            if (is_event && !is_filter && !is_today && !is_log) { stl.fg = st.col_event; stl.dim = true; }
            if (st.focus == Focus::Calendar && d == st.cursor) stl.inverted = true;
            if (!stl.dim && !has_underline && stl.fg.is_default() && !(st.focus == Focus::Calendar && d == st.cursor)) {
                // plain date keeps dim
            }
            char buf[8];
            snprintf(buf, sizeof(buf), "%2d", daynum);
            std::string num = buf;
            // pad spaces keep the base style
            int numx = b.x + 1 + 3 * i + (3 - 1 - (int)num.size());
            draw_text(s, b.x + 1 + 3 * i, y, std::string(3 - 1 - (int)num.size(), ' '), base);
            draw_text(s, numx, y, num, stl);
        }
        ++y;
    }
}

static int year_box_width(int mcols) { return mcols * 23 + 2; }

static void draw_calendar(Screen& s, const Box& b, const AppState& st, const Style& border_st) {
    draw_box(s, b, border_st);
    std::string ytitle = fmt(st.year);
    draw_text(s, b.x + 1, b.y, ytitle, border_st);
    int inner_w = std::max(0, b.w - 2);
    int inner_h = std::max(0, b.h - 2);
    int mcols = std::max(1, (inner_w - 2) / 23);
    int cellw = 23;
    int rows = 12 / mcols;
    // vertical layout: bottom aligned, clip from the top
    std::vector<int> row_h;
    for (int r = 0; r < rows; ++r) {
        int mh = 0;
        for (int c = 0; c < mcols; ++c) {
            int m = r * mcols + c;
            if (m > 11) continue;
            Date d; d.y = st.year; d.m = m + 1; d.d = 1;
            mh = std::max(mh, weeks_in_month(d, st.logs.sunday_start) + 2);
        }
        row_h.push_back(mh);
    }
    int total = 0;
    for (int h : row_h) total += h;
    int yoff = inner_h - total;   // may be negative
    int y = b.y + 1 + yoff;
    for (int r = 0; r < rows; ++r) {
        int x = b.x + 1;
        for (int c = 0; c < mcols; ++c) {
            int m = r * mcols + c;
            if (m > 11) break;
            Box mb{x, y, cellw, row_h[r]};
            draw_month(s, mb, st.year, m, st, border_st);
            x += cellw;
        }
        y += row_h[r];
    }
}

// ---------- preview ----------
static void draw_preview(Screen& s, const Box& b, const AppState& st, const Style& border_st) {
    draw_box(s, b, border_st);
    std::string title;
    const LogEntry* e = st.logs.entry(st.cursor);
    if (st.needs_password) title = "log preview";
    else title = "log preview for " + date_str_short(st.cursor);
    Style ts = border_st; ts.bold = true; ts.underline = true;
    // centered
    int tw = (int)title.size();
    int tx = b.x + 1 + std::max(0, (b.w - 2 - tw) / 2);
    draw_text(s, tx, b.y, title, ts);
    std::vector<std::string> lines;
    if (e) {
        if (st.logs.encrypted) {
            std::string content;
            if (read_file(e->path, &content)) {
                std::string dec = aes_cfb_decrypt(derive_key(st.logs.password), std::string((const char*)kDefaultIv, 16), content);
                lines = split_lines(dec);
            }
        } else {
            lines = e->lines;
        }
    } else if (!st.needs_password) {
        // no log: read the file if it exists
        char sub[32]; snprintf(sub, sizeof(sub), "y%d", st.cursor.y);
        std::string p = st.logs.dir + "/" + sub + "/" + log_filename(st.cursor, st.logs.name_format);
        std::string content;
        if (read_file(p, &content)) lines = split_lines(content);
    }
    auto md = render_markdown(lines, st);
    int y = b.y + 1;
    int rows = std::max(0, b.h - 2);
    int inner_w = std::max(0, b.w - 2);
    for (auto& l : md) {
        if (rows <= 0) break;
        std::string t = l.text;
        if ((int)t.size() > inner_w) t = t.substr(0, inner_w);
        draw_text(s, b.x + 1, y, t, l.st);
        ++y; --rows;
    }
}

// ---------- main view ----------
static void draw_main(Screen& s, const AppState& st) {
    int W = s.w, H = s.h;
    bool term256 = getenv("CL_256") != nullptr;
    Style defst;
    Style menu_border; menu_border.dim = st.focus != Focus::Sections;
    // compute layout
    int mcols = (W >= 205) ? 6 : (W >= 145) ? 4 : (W >= 105) ? 3 : (W >= 68) ? 2 : 1;
    int yw = year_box_width(mcols);
    int menu_w = 25;
    int left_w = menu_w * 2;
    int hbox_w = left_w + yw + 1;
    std::string help = "hjkl/arrow keys - navigation | d - delete log | s - see scratchpads | tab - move focus between menus and calendar";
    int help_w = (int)help.size();
    std::string title = title_text(st);
    int title_w = (int)title.size();
    int content_w = std::max(hbox_w, std::max(title_w, help_w));
    content_w = std::min(content_w, W);
    // shrink the hbox if needed
    int lw = left_w, cyw = yw;
    if (hbox_w > content_w) {
        auto parts = distribute({left_w, yw, 1}, content_w - 1);
        lw = parts[0]; cyw = parts[1];
        hbox_w = lw + cyw + 1;
    }
    int pad_x = (W - content_w) / 2;
    if (pad_x < 0) pad_x = 0;
    // vertical layout
    int menus_h = 20;
    int events_h = 2;
    int left_h = menus_h + events_h;
    int cal_rows = 12 / mcols;
    int cal_h = 2;
    for (int r = 0; r < cal_rows; ++r) {
        int mh = 0;
        for (int c = 0; c < mcols; ++c) {
            int m = r * mcols + c;
            if (m > 11) continue;
            Date d; d.y = st.year; d.m = m + 1; d.d = 1;
            mh = std::max(mh, weeks_in_month(d, st.logs.sunday_start) + 2);
        }
        cal_h += mh;
    }
    int hbox_h = std::max(left_h, cal_h);
    int preview_h = 14;
    int content_h = 1 + hbox_h + preview_h + 1;
    content_h = std::min(content_h, H);
    // shrink
    int hh = hbox_h, ph = preview_h;
    bool has_help = true;
    if (1 + hbox_h + preview_h + 1 > H) {
        // distribute the deficit
        int avail = H - 1;   // title row
        auto parts = distribute({hbox_h, preview_h, 1}, avail);
        hh = parts[0]; ph = parts[1]; has_help = parts[2] > 0;
        if (!has_help) ph = parts[1];
    }
    int pad_y = (H - (1 + hh + ph + (has_help ? 1 : 0))) / 2;
    if (pad_y < 0) pad_y = 0;
    int y = pad_y;
    // title
    {
        Style ts; ts.bold = true; ts.underline = true;
        int tx = pad_x + std::max(0, (content_w - title_w) / 2);
        if (title_w > content_w) tx = pad_x;
        draw_text(s, tx, y, title.substr(0, std::min(title_w, content_w)), ts);
        ++y;
    }
    // main area
    int area_h = hh;
    int x = pad_x;
    // left column
    Box lb{x, y, lw, area_h};
    {
        Box mb{x, y, lw, menus_h};
        // two menus
        int mw1 = menu_w, mw2 = menu_w;
        if (lw < menu_w * 2) {
            auto parts = distribute({menu_w, menu_w}, lw);
            mw1 = parts[0]; mw2 = parts[1];
        }
        Style b1; b1.dim = (st.focus != Focus::Sections);
        Style b2; b2.dim = (st.focus != Focus::Tags);
        std::vector<std::string> sn; std::vector<int> sc;
        sn.push_back(std::string()); sc.push_back(0);
        for (auto& sec : st.sections) {
            sn.push_back(sec);
            sc.push_back((int)st.logs.section_dates[sec].size());
        }
        draw_menu(s, Box{x, y, mw1, menus_h}, "Sections", sn, sc, st.section_idx, st.focus == Focus::Sections, b1);
        std::vector<std::string> tn; std::vector<int> tc;
        tn.push_back(std::string()); tc.push_back(0);
        auto tagmap = st.logs.tags_sorted_map(st.selected_section());
        for (auto& t : tagmap) { tn.push_back(t.first); tc.push_back((int)t.second.size()); }
        draw_menu(s, Box{x + mw1, y, mw2, menus_h}, "Tags", tn, tc, st.tag_idx, st.focus == Focus::Tags, b2);
    }
    Box eb{x, y + menus_h, lw, std::min(events_h, std::max(0, area_h - menus_h))};
    if (eb.h >= 2) draw_events(s, eb, st, Style());
    // calendar
    Box cb{x + lw, y, cyw, area_h};
    if (cyw > 2) {
        Style bs; bs.dim = (st.focus != Focus::Calendar);
        draw_calendar(s, cb, st, bs);
    }
    y += area_h;
    // preview
    Box pb{pad_x, y, content_w, ph};
    if (ph >= 2) {
        Style bs; bs.dim = true;
        draw_preview(s, pb, st, bs);
    }
    y += ph;
    // help
    if (has_help) {
        Style hs; hs.dim = true;
        int tx = pad_x + std::max(0, (content_w - help_w) / 2);
        if (help_w > content_w) tx = pad_x;
        draw_text(s, tx, y, help.substr(0, std::min(help_w, content_w)), hs);
    }
    (void)term256;
}

}  // namespace cl
