// ---------- scratchpad view ----------
static void draw_scratchpad(Screen& s, const AppState& st) {
    int W = s.w, H = s.h;
    std::string title = "Scratchpad Manager";
    std::string help = "Press F1 for help.";
    int content_h = 27;
    int extra = H - content_h;
    int top = extra > 0 ? extra / 3 : 0;
    int y = top;
    Style ts; ts.bold = true;
    int tx = std::max(0, (W - (int)title.size()) / 2);
    draw_text(s, tx, y, title, ts);
    ++y;
    // separator line
    for (int i = 0; i < W; ++i) s.put(i, y, 0x2500, Style());
    ++y;
    int main_h = std::max(0, content_h - 4);
    int menu_w = 44;
    // scratchpad menu
    {
        Box mb{0, y, menu_w, main_h};
        draw_box(s, mb, Style());
        draw_text(s, 1, y, "Scratchpads", Style());
        int rows = std::max(0, main_h - 2);
        int i = 0;
        // entry 0: make new
        if (rows > 0) {
            Style es;
            if (st.focus == Focus::Sections && st.scratch_idx == 0) { es.bold = true; es.inverted = true; }
            std::string line = std::string(1, (st.scratch_idx == 0) ? '>' : ' ') + " Make new scratchpad";
            if ((int)line.size() > menu_w - 2) line = line.substr(0, menu_w - 2);
            draw_text(s, 1, y + 1, line, es);
            i = 1;
        }
        for (auto& sp : st.scratchpads) {
            if (i >= rows) break;
            Style es;
            if (st.focus == Focus::Sections && st.scratch_idx == i) { es.bold = true; es.inverted = true; }
            std::string line = std::string(1, (st.scratch_idx == i) ? '>' : ' ') + " " + sp.name;
            // right aligned date YY-MM-DD
            std::string ds = fmt2((st.today.y % 100));
            (void)ds;
            struct stat sb;
            time_t mt = 0;
            if (stat(sp.path.c_str(), &sb) == 0) mt = sb.st_mtime;
            struct tm tmv;
            localtime_r(&mt, &tmv);
            char db[32];
            snprintf(db, sizeof(db), "%02d-%02d-%02d", (tmv.tm_year + 1900) % 100, tmv.tm_mon + 1, tmv.tm_mday);
            std::string dstr = db;
            int pad = menu_w - 2 - (int)line.size() - (int)dstr.size();
            if (pad < 1) pad = 1;
            line += std::string(pad, ' ') + dstr;
            if ((int)line.size() > menu_w - 2) line = line.substr(0, menu_w - 2);
            draw_text(s, 1, y + 1 + i, line, es);
            ++i;
        }
    }
    // preview
    {
        Box pb{menu_w, y, W - menu_w, main_h};
        draw_box(s, pb, Style());
        int rows = std::max(0, main_h - 2);
        if (st.scratch_idx == 0 || st.scratch_idx > (int)st.scratchpads.size()) {
            std::string t = "Select a scratchpad";
            Style hs; hs.bold = true; hs.underline = true;
            int tx = menu_w + 1 + std::max(0, ((W - menu_w - 2) - (int)t.size()) / 2);
            draw_text(s, tx, y + 1, t, hs);
            if (rows > 1) draw_text(s, menu_w + 1, y + 2, "No scratchpad selected", Style());
        } else {
            const Scratchpad& sp = st.scratchpads[st.scratch_idx - 1];
            std::string t = sp.name;
            Style hs; hs.bold = true; hs.underline = true;
            int tx = menu_w + 1 + std::max(0, ((W - menu_w - 2) - (int)t.size()) / 2);
            draw_text(s, tx, y + 1, t, hs);
            std::string content;
            if (read_file(sp.path, &content)) {
                auto lines = split_lines(content);
                auto md = render_markdown(lines, st);
                int yy = y + 2;
                for (auto& l : md) {
                    if (yy >= y + main_h - 1) break;
                    std::string t2 = l.text;
                    if ((int)t2.size() > W - menu_w - 2) t2 = t2.substr(0, W - menu_w - 2);
                    draw_text(s, menu_w + 1, yy, t2, l.st);
                    ++yy;
                }
            }
        }
    }
    y += main_h;
    int hx = std::max(0, (W - (int)help.size()) / 2);
