static void draw_help_overlay(Screen& s, const AppState& st) {
    (void)st;
    int W = s.w, H = s.h;
    int bw = 114, bh = 47;
    int x = (W - bw) / 2; if (x < 0) x = 0;
    int y = (H - bh) / 2; if (y < 0) y = 0;
    if (y + bh > H) bh = H - y;
    if (x + bw > W) bw = W - x;
    Style bs;
    draw_box_merge(s, Box{x, y, bw, bh}, bs);
    // content
    int n = (int)(sizeof(kHelpLines) / sizeof(kHelpLines[0]));
    for (int i = 0; i < n && y + 1 + i < y + bh - 1; ++i) {
        std::string line = kHelpLines[i];
        Style stl;
        if (line.size() >= 2 && line.compare(0, 2, "  ") == 0 && line.size() > 2 && line[2] == '-') {
            stl.dim = true;
        }
        // markdown-ish styling for special lines
        std::string t = line;
        draw_text(s, x + 1, y + 1 + i, t.substr(0, std::min(t.size(), (size_t)(bw - 2))), stl);
    }
    // bold segment for Caption's Log
    {
        std::string line = kHelpLines[5];
        Style bs2; bs2.bold = true;
        std::string seg = "Caption's Log";
        size_t p = line.find(seg);
        if (p != std::string::npos)
            draw_text(s, x + 1 + (int)p, y + 1 + 5, seg, bs2);
    }
    // link
    {
        std::string line = kHelpLines[13];
        Style ls; ls.bold = true; ls.underline = true;
        size_t p = line.find("https://");
        if (p != std::string::npos) {
            std::string seg = line.substr(p);
            draw_text(s, x + 1 + (int)p, y + 1 + 13, seg, ls);
        }
    }
    // code segments
    {
        Style cs; cs.fg = Color::a16(7);
        std::string line = kHelpLines[15];
        size_t p = line.find("`* tagname`");
        if (p != std::string::npos) draw_text(s, x + 1 + (int)p + 1, y + 1 + 15, "* tagname", cs);
        line = kHelpLines[17];
        p = line.find("`# sectionname`");
        if (p != std::string::npos) draw_text(s, x + 1 + (int)p + 1, y + 1 + 17, "# sectionname", cs);
    }
    // separator + close button
    int sep_y = y + 1 + n;
    if (sep_y < y + bh - 1) {
        for (int i = 1; i < bw - 1; ++i) s.put(x + i, sep_y, 0x2500, Style());
        s.put(x, sep_y, 0x251C, Style());
        s.put(x + bw - 1, sep_y, 0x2524, Style());
    }
    int by = sep_y + 1;
    if (by + 2 < y + bh - 1) {
        int bwid = 7;
        int bx = x + 1 + std::max(0, (bw - 2 - bwid) / 2);
        Style vs; vs.inverted = true;
        s.put(bx, by, 0x250C, vs);
        for (int i = 1; i < bwid - 1; ++i) s.put(bx + i, by, 0x2500, vs);
        s.put(bx + bwid - 1, by, 0x2510, vs);
        s.put(bx, by + 1, 0x2502, vs);
        draw_text(s, bx + 1, by + 1, "Close", vs);
        s.put(bx + bwid - 1, by + 1, 0x2502, vs);
        s.put(bx, by + 2, 0x2514, vs);
        for (int i = 1; i < bwid - 1; ++i) s.put(bx + i, by + 2, 0x2500, vs);
        s.put(bx + bwid - 1, by + 2, 0x2518, vs);
    }
}

// generic dialog: question + optional input + buttons
static void draw_dialog(Screen& s, const std::string& question, const std::string& input,
                        const std::vector<std::string>& buttons, int sel, bool masked) {
    int W = s.w, H = s.h;
    int bw = (int)question.size() + 2;
    if (bw < 30) bw = 30;
    int bh = 2 + 1 + (buttons.empty() ? 1 : 3);
    int x = (W - bw) / 2; if (x < 0) x = 0;
    int y = (H - bh) / 2; if (y < 0) y = 0;
    Style bs; bs.dim = true; bs.fg = Color::a16(8);
    draw_box_merge(s, Box{x, y, bw, bh}, bs);
    draw_text(s, x + 1, y, question, bs);
    // separator
    int sy = y + 1;
    for (int i = 1; i < bw - 1; ++i) s.put(x + i, sy, 0x2500, bs);
    s.put(x, sy, 0x251C, bs);
    s.put(x + bw - 1, sy, 0x2524, bs);
    // input line
    int iy = sy + 1;
    if (!input.empty()) {
        std::string shown;
        if (masked) {
            for (size_t i = 0; i < input.size(); ++i) shown += "\xe2\x80\xa2";
        } else shown = input;
        Style is; is.inverted = true;
        draw_text(s, x + 1 + 10, iy, shown, is);
    }
    // buttons
    if (!buttons.empty()) {
        int total = 0;
        for (auto& b : buttons) total += (int)b.size() + 2;
        int bx = x + 1 + std::max(0, (bw - 2 - total) / 2);
        int by = iy + 1;
        for (size_t i = 0; i < buttons.size(); ++i) {
            int w = (int)buttons[i].size() + 2;
            Style vs; vs.inverted = true;
            s.put(bx, by, 0x250C, vs);
            for (int k = 1; k < w - 1; ++k) s.put(bx + k, by, 0x2500, vs);
            s.put(bx + w - 1, by, 0x2510, vs);
            s.put(bx, by + 1, 0x2502, vs);
            draw_text(s, bx + 1, by + 1, buttons[i], vs);
            s.put(bx + w - 1, by + 1, 0x2502, vs);
            s.put(bx, by + 2, 0x2514, vs);
            for (int k = 1; k < w - 1; ++k) s.put(bx + k, by + 2, 0x2500, vs);
            s.put(bx + w - 1, by + 2, 0x2518, vs);
            bx += w;
        }
    }
}

// ---------- top-level render ----------
void render_screen(AppState& st, Screen& s) {
    s.fill(0, 0, s.w, s.h, ' ', Style());
    if (st.view == View::Scratchpad) draw_scratchpad(s, st);
    else draw_main(s, st);
    switch (st.overlay) {
        case Overlay::Help: draw_help_overlay(s, st); break;
        case Overlay::Delete:
            draw_dialog(s, st.dialog_text, "", {"Yes", "No"}, 0, false);
            break;
        case Overlay::Password:
            draw_dialog(s, "Enter password for log files:", st.input, {"Submit"}, 0, true);
            break;
        case Overlay::Rename:
            draw_dialog(s, st.dialog_text, st.input, {"Submit"}, 0, false);
            break;
        default: break;
    }
}

