static Args parse_args(int argc, char** argv) {
    Args a;
    for (int i = 1; i < argc; ++i) {
        std::string s = argv[i];
        auto val = [&](const char* name) -> bool {
            if (s == name && i + 1 < argc) { return true; }
            return false;
        };
        if (s == "-h" || s == "--help") { a.help = true; }
        else if (s == "-c" || s == "--config") { if (i + 1 < argc) { a.config = argv[++i]; a.config_set = true; } }
        else if (s == "--log-dir-path") { if (i + 1 < argc) { a.log_dir = argv[++i]; a.log_dir_set = true; } }
        else if (s == "--log-name-format") { if (i + 1 < argc) { a.name_format = argv[++i]; a.name_format_set = true; } }
        else if (s == "--sunday-start") { a.sunday_start = true; a.sunday_set = true; }
        else if (s == "--first-line-section") { a.first_line = true; a.first_line_set = true; }
        else if (s == "--password") { if (i + 1 < argc) { a.password = argv[++i]; a.password_set = true; } }
        else if (s == "--encrypt") { a.encrypt = true; }
        else if (s == "--decrypt") { a.decrypt = true; }
    }
    return a;
}

static void fail(const std::string& msg) {
    fprintf(stderr, "Captain's log encountered an error: \n %s\n", msg.c_str());
}

static bool list_files(const std::string& dir, std::vector<std::string>* out) {
    DIR* dp = opendir(dir.c_str());
    if (!dp) return false;
    struct dirent* de;
    while ((de = readdir(dp)) != nullptr) {
        std::string n = de->d_name;
        if (n == "." || n == "..") continue;
        out->push_back(n);
    }
    closedir(dp);
    std::sort(out->begin(), out->end());
    return true;
}

// recursively collect the log files matching the name format
static void collect_log_files(const std::string& dir, const std::string& format,
                              std::vector<std::string>* out) {
    std::vector<std::string> entries;
    if (!list_files(dir, &entries)) return;
    for (auto& e : entries) {
        std::string full = dir + "/" + e;
        struct stat st;
        if (stat(full.c_str(), &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) {
            collect_log_files(full, format, out);
        } else {
            Date d;
            if (match_format(format, e, &d)) out->push_back(full);
        }
    }
}

static bool decrypt_if_valid(const std::string& key, const std::string& iv,
                             const std::string& content, std::string* out) {
    std::string dec = aes_cfb_decrypt(key, iv, content);
    std::string re = aes_cfb_encrypt(key, iv, dec);
    if (re != content) return false;
    *out = dec;
    return true;
}

static int apply_crypto(const Config& cfg, bool encrypt) {
    printf("Applying crypto...\n");
    std::string iv((const char*)kDefaultIv, 16);
    std::string key = derive_key(cfg.password);
    std::string dir = cfg.log_dir_path;
    std::vector<std::string> files;
    collect_log_files(dir, cfg.log_name_format, &files);
    std::string cle = dir + "/.cle";
    if (encrypt) {
        if (file_exists(cle)) { fail("Already applied"); return 1; }
        for (auto& f : files) {
            std::string content;
            if (!read_file(f, &content)) continue;
            std::string enc = aes_cfb_encrypt(key, iv, content);
            write_file(f, enc);
        }
        write_file(cle, aes_cfb_encrypt(key, iv, kEncMarker));
        return 0;
    } else {
        if (!file_exists(cle)) { fail("Already applied"); return 1; }
        for (auto& f : files) {
            std::string content;
            if (!read_file(f, &content)) continue;
            std::string dec;
            if (decrypt_if_valid(key, iv, content, &dec)) write_file(f, dec);
        }
        unlink(cle.c_str());
        return 0;
    }
}

