static void open_editor(const std::string& path) {
    const char* ed = getenv("EDITOR");
    if (!ed || !*ed) return;
    std::string cmd = ed;
    cmd += " '";
    for (char c : path) { if (c == '\'') cmd += "'\\''"; else cmd += c; }
    cmd += "'";
    int rc = system(cmd.c_str());
    (void)rc;
}

static void move_cursor(AppState& st, int dx, int dy) {
    Date d = st.cursor;
    if (dx == -1) {
        if (d.d == 1) {
            d.m -= 1;
            if (d.m < 1) { d.m = 12; d.y -= 1; }
            d.d = 1;
        } else d.d -= 1;
    } else if (dx == 1) {
        d.d += 1;
        if (d.d > d.days_in_month()) { d.m += 1; if (d.m > 12) { d.m = 1; d.y += 1; } d.d = 1; }
    } else if (dy != 0) {
        Date nd = d.add_days(dy * 7);
        if (nd.y != d.y) {
            // keep within the displayed year
            if (dy < 0) { nd.y = d.y; nd.m = 1; nd.d = 1; }
            else { nd.y = d.y; nd.m = 12; nd.d = 1; }
        } else if (nd.m != d.m) {
            nd.d = 1;
        }
        d = nd;
    }
    if (d.y != st.year) {
        d.y = st.year;
        if (d.m == 1 && d.d == 1) { /* keep */ }
        else { d.m = st.cursor.m; d.d = 1; }
    }
    st.cursor = d;
}

static void set_year(AppState& st, int y) {
    st.year = y;
    Date d = st.cursor;
    d.y = y;
    if (d.d > d.days_in_month()) d.d = d.days_in_month();
    st.cursor = d;
    scan_dir(st.logs, y, nullptr);
    st.reload_menus();
}

static void handle_key(AppState& st, const KeyEv& ev, Ui& ui);

static void run_tui(AppState& st) {
    Ui ui;
    ui.setup();
    ui.draw(st);
    while (!st.quit) {
        KeyEv ev;
        if (!ui.term.read_key(ev, 200)) {
            // timeout: check for resize
            ui.draw(st);
            continue;
        }
        handle_key(st, ev, ui);
        ui.draw(st);
    }
    ui.teardown();
}

static void handle_key(AppState& st, const KeyEv& ev, Ui& ui) {
    (void)ui;
    // overlay handling
    if (st.overlay == Overlay::Help) {
        if (ev.type == KeyType::F1 || ev.type == KeyType::Escape || ev.type == KeyType::Enter ||
            (ev.type == KeyType::Char && (ev.ch == 'q' || ev.ch == 'Q'))) {
            st.overlay = Overlay::None;
        }
        return;
    }
    if (st.overlay == Overlay::Delete) {
        if (ev.type == KeyType::Left || ev.type == KeyType::Char && ev.ch == 'h') {
            st.input = (st.input.empty() ? "1" : "0");
        } else if (ev.type == KeyType::Right || ev.type == KeyType::Char && ev.ch == 'l') {
            st.input = "1";
        } else if (ev.type == KeyType::Enter) {
            bool yes = st.input != "1";
            st.overlay = Overlay::None;
            if (yes) {
                if (st.view == View::Scratchpad) {
                    if (st.scratch_idx >= 1 && st.scratch_idx <= (int)st.scratchpads.size())
                        unlink(st.scratchpads[st.scratch_idx - 1].path.c_str());
                    scan_scratchpads(st);
                } else {
                    char sub[32]; snprintf(sub, sizeof(sub), "y%d", st.cursor.y);
                    std::string p = st.logs.dir + "/" + sub + "/" + log_filename(st.cursor, st.logs.name_format);
                    unlink(p.c_str());
                    scan_dir(st.logs, st.year, nullptr);
                    st.reload_menus();
                }
            }
        } else if (ev.type == KeyType::Escape) {
            st.overlay = Overlay::None;
        }
        return;
    }
    if (st.overlay == Overlay::Password || st.overlay == Overlay::Rename) {
        bool masked = st.overlay == Overlay::Password;
        if (ev.type == KeyType::Backspace) {
            if (!st.input.empty()) st.input.pop_back();
            return;
        }
        if (ev.type == KeyType::Enter) {
            std::string val = st.input;
            st.input.clear();
            if (st.overlay == Overlay::Password) {
                std::string key = derive_key(val);
                std::string iv((const char*)kDefaultIv, 16);
                std::string cle = st.logs.dir + "/.cle";
                std::string content;
                if (read_file(cle, &content)) {
                    std::string dec = aes_cfb_decrypt(key, iv, content);
                    if (dec == kEncMarker) {
                        st.logs.password = val;
                        st.logs.encrypted = true;
                        st.needs_password = false;
                        st.overlay = Overlay::None;
                        scan_dir(st.logs, st.year, nullptr);
                        st.reload_menus();
                        return;
                    }
                }
                fail("Invalid password provided!");
                st.quit = true;
                return;
            } else {
                // rename
                if (!val.empty()) {
                    const Scratchpad* sp = nullptr;
                    if (st.scratch_idx >= 1 && st.scratch_idx <= (int)st.scratchpads.size())
                        sp = &st.scratchpads[st.scratch_idx - 1];
                    if (sp) {
                        std::string nd = st.logs.dir + "/scratchpads/" + val + ".md";
                        rename(sp->path.c_str(), nd.c_str());
                        scan_scratchpads(st);
                    }
                }
                st.overlay = Overlay::None;
                return;
            }
        }
        if (ev.type == KeyType::Escape) { st.overlay = Overlay::None; st.input.clear(); return; }
        if (ev.type == KeyType::Char) {
            // utf-8 encode
            uint32_t c = ev.ch;
            std::string s;
            if (c < 0x80) s += (char)c;
            else if (c < 0x800) { s += (char)(0xC0 | (c >> 6)); s += (char)(0x80 | (c & 0x3F)); }
            else { s += (char)(0xE0 | (c >> 12)); s += (char)(0x80 | ((c >> 6) & 0x3F)); s += (char)(0x80 | (c & 0x3F)); }
            st.input += s;
        }
        return;
    }
    // view handling
    if (ev.type == KeyType::F1) { st.overlay = Overlay::Help; return; }
    if (ev.type == KeyType::Char && (ev.ch == 'q' || ev.ch == 'Q')) { st.quit = true; return; }
    if (ev.type == KeyType::Escape) { st.quit = true; return; }
    if (ev.type == KeyType::Tab) {
        st.focus = (Focus)(((int)st.focus + 1) % 3);
        return;
    }
    if (ev.type == KeyType::BackTab) {
        st.focus = (Focus)(((int)st.focus + 2) % 3);
        return;
    }
    if (st.view == View::Scratchpad) {
        if (ev.type == KeyType::Char && ev.ch == 's') { st.view = View::Main; return; }
        if (ev.type == KeyType::Down || (ev.type == KeyType::Char && ev.ch == 'j')) {
            if (st.scratch_idx < (int)st.scratchpads.size()) ++st.scratch_idx;
            return;
        }
        if (ev.type == KeyType::Up || (ev.type == KeyType::Char && ev.ch == 'k')) {
            if (st.scratch_idx > 0) --st.scratch_idx;
            return;
        }
        if (ev.type == KeyType::Enter) {
            if (st.scratch_idx == 0) {
                // make new scratchpad
            } else if (st.scratch_idx <= (int)st.scratchpads.size()) {
                open_editor(st.scratchpads[st.scratch_idx - 1].path);
            }
            scan_scratchpads(st);
            return;
        }
        if (ev.type == KeyType::Char && ev.ch == 'd') {
            st.overlay = Overlay::Delete;
            st.dialog_text = "Are you sure you want to delete a scratchpad?";
            st.input = "0";
            return;
        }
        if (ev.type == KeyType::Char && ev.ch == 'r') {
            if (st.scratch_idx >= 1 && st.scratch_idx <= (int)st.scratchpads.size()) {
                st.dialog_text = "Enter the new name for the scratchpad \"" +
                                 st.scratchpads[st.scratch_idx - 1].name + "\":";
                st.input.clear();
                st.overlay = Overlay::Rename;
            }
            return;
        }
        return;
    }
    // main view
    switch (ev.type) {
        case KeyType::Char: {
            char c = (char)ev.ch;
            if (c == 'h') move_cursor(st, -1, 0);
            else if (c == 'l') move_cursor(st, 1, 0);
            else if (c == 'k') move_cursor(st, 0, -1);
            else if (c == 'j') move_cursor(st, 0, 1);
            else if (c == 'r') {
                // rename (only in scratchpad view)
            } else if (c == 's') {
                st.view = View::Scratchpad;
                scan_scratchpads(st);
            } else if (c == 'd') {
                if (st.logs.has_log(st.cursor)) {
                    st.overlay = Overlay::Delete;
                    st.dialog_text = "Are you sure you want to delete a log file?";
                    st.input = "0";
                }
            }
            break;
        }
        case KeyType::Left: move_cursor(st, -1, 0); break;
        case KeyType::Right: move_cursor(st, 1, 0); break;
        case KeyType::Up: move_cursor(st, 0, -1); break;
        case KeyType::Down: move_cursor(st, 0, 1); break;
        case KeyType::Enter: {
            char sub[32]; snprintf(sub, sizeof(sub), "y%d", st.cursor.y);
            std::string dir = st.logs.dir + "/" + sub;
            mkdir(dir.c_str(), 0755);
            std::string p = dir + "/" + log_filename(st.cursor, st.logs.name_format);
            if (!file_exists(p)) write_file(p, "# " + date_str_short(st.cursor) + "\n");
            open_editor(p);
            scan_dir(st.logs, st.year, nullptr);
            st.reload_menus();
            break;
        }
        case KeyType::Backspace: break;
        default: break;
    }
    // +/- handled separately (they may come as chars)
}

