namespace cl {

bool file_exists(const std::string& p) {
    struct stat st;
    return stat(p.c_str(), &st) == 0;
}
bool read_file(const std::string& path, std::string* out) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return false;
    out->clear();
    char buf[8192];
    size_t r;
    while ((r = fread(buf, 1, sizeof(buf), f)) > 0) out->append(buf, r);
    fclose(f);
    return true;
}
bool write_file(const std::string& path, const std::string& data) {
    FILE* f = fopen(path.c_str(), "wb");
    if (!f) return false;
    fwrite(data.data(), 1, data.size(), f);
    fclose(f);
    return true;
}
std::vector<std::string> split_lines(const std::string& s) {
    std::vector<std::string> out;
    size_t pos = 0;
    while (pos <= s.size()) {
        size_t nl = s.find('\n', pos);
        if (nl == std::string::npos) {
            std::string line = s.substr(pos);
            if (!line.empty()) out.push_back(line);
            break;
        }
        std::string line = s.substr(pos, nl - pos);
        if (!line.empty() && line.back() == '\r') line.pop_back();
        out.push_back(line);
        pos = nl + 1;
    }
    return out;
}
std::string join_lines(const std::vector<std::string>& lines) {
    std::string out;
    for (auto& l : lines) { out += l; out += "\n"; }
    return out;
}
std::string home_expand(const std::string& p) {
    if (p.empty()) return p;
    if (p[0] == '~') {
        const char* h = getenv("HOME");
        std::string hp = h ? h : "";
        return hp + p.substr(1);
    }
    return p;
}
std::string date_str_full(const Date& d) {
    char b[64];
    snprintf(b, sizeof(b), "%02d. %02d. %d.", d.d, d.m, d.y);
    return b;
}
std::string date_str_short(const Date& d) {
    char b[64];
    snprintf(b, sizeof(b), "%02d. %02d. %02d.", d.d, d.m, d.y % 100);
    return b;
}
bool match_format(const std::string& fmt, const std::string& name, Date* out) {
    size_t fi = 0, ni = 0;
    int y = 0, m = 0, d = 0;
    bool have_y = false, have_m = false, have_d = false;
    while (fi < fmt.size()) {
        if (fmt[fi] == '%' && fi + 1 < fmt.size()) {
            char c = fmt[fi + 1];
            ++fi;
            int digits = (c == 'Y') ? 4 : (c == 'y' ? 2 : 2);
            if (c != 'Y' && c != 'y' && c != 'm' && c != 'd') {
                if (ni >= name.size() || name[ni] != '%') return false;
                ++ni; ++fi; continue;
            }
            int val = 0, cnt = 0;
            while (ni < name.size() && cnt < digits && isdigit((unsigned char)name[ni])) {
                val = val * 10 + (name[ni] - '0');
                ++ni; ++cnt;
            }
            if (cnt != digits) return false;
            if (c == 'Y') { y = val; have_y = true; }
            else if (c == 'y') { y = 2000 + val; have_y = true; }
            else if (c == 'm') { m = val; have_m = true; }
            else { d = val; have_d = true; }
            ++fi;
        } else {
            if (ni >= name.size() || name[ni] != fmt[fi]) return false;
            ++ni; ++fi;
        }
    }
    if (ni != name.size()) return false;
    if (!have_y || !have_m || !have_d) return false;
    out->y = y; out->m = m; out->d = d;
    return out->valid();
}
void fail(const std::string& msg) {
    fprintf(stderr, "Captain's log encountered an error: \n %s\n", msg.c_str());
}

}  // namespace cl
